    private void BtnCari1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BtnCari1ActionPerformed
        if (NoRM.getText().equals("") || NmPasien.getText().equals("")) {
            JOptionPane.showMessageDialog(null, "Pasien masih kosong...!!!");
        } else {
            Valid.hapusFileDalamFolder("/gambargrafik/");
            Valid.hapusFileDalamFolder("/gambargrafikpatograf/");
            Valid.hapusFileDalamFolder("/tmpImageFreehand/");
            Valid.hapusFileDalamFolder("/tmpImageHandover/");
            Valid.hapusFileDalamFolder("/tmpImageImplant/");
            Valid.hapusFiledanFolderDalamFolder("dicom_images");
            Valid.hapusFileDalamFolder("/cache_berkas/");

            int selectedTab = TabRawat.getSelectedIndex();

            // Cancel any existing workers
            if (currentPerawatanWorker != null && !currentPerawatanWorker.isDone()) {
                currentPerawatanWorker.cancel(true);
            }
            if (currentSoapiWorker != null && !currentSoapiWorker.isDone()) {
                currentSoapiWorker.cancel(true);
            }

            switch (selectedTab) {
                case 0:
                    this.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
                    tampilKunjungan();
                    this.setCursor(Cursor.getDefaultCursor());
                    Scroll.getVerticalScrollBar().setValue(0);
                    Scroll.getViewport().setViewPosition(new Point(0, 0));
                    break;
                case 1:
                    // Use SwingWorker for SOAPI tab
                    showProgress("Memuat data S.O.A.P.I...");
                    currentSoapiWorker = new SoapiSwingWorker();
                    currentSoapiWorker.execute();
                    break;
                case 2:
                    // Use SwingWorker for Perawatan tab
                    showProgress("Memuat data riwayat perawatan...");
                    currentPerawatanWorker = new PerawatanSwingWorker();
                    currentPerawatanWorker.execute();
                    break;
                case 3:
                    // Use SwingWorker for Satu Sehat tab
                    tampilSatuSehat();
                    break;
                case 4:
                    // Use SwingWorker for SBAR tab
                    showProgress("Memuat data SBAR...");
                    new SBARSwingWorker().execute();
                    break;
                case 5:
                    // Use SwingWorker for Retensi tab
                    showProgress("Memuat data retensi berkas medik...");
                    new RetensiSwingWorker().execute();
                    break;
                case 6:
                    // Use SwingWorker for PRMPRJ tab
                    showProgress("Memuat data PRMPRJ...");
                    new PRMPRJSwingWorker().execute();
                    break;
                case 7:
                    // Use SwingWorker for Imaging/Radiology tab
                    tampilImagingRadiology();
                    break;
                default:
                    break;
            }

            // Reset scroll position for tabs that don't use SwingWorker
            if (selectedTab != 1 && selectedTab != 2) {
                LoadHTMLRiwayatPerawatan.setSelectionStart(0);
                LoadHTMLRiwayatPerawatan.setSelectionEnd(0);
                LoadHTMLSOAPI.setSelectionStart(0);
                LoadHTMLSOAPI.setSelectionEnd(0);
                LoadHTMLPRMPRJ.setSelectionStart(0);
                LoadHTMLPRMPRJ.setSelectionEnd(0);
//                LoadHTMLPembelian.setSelectionStart(0);
//                LoadHTMLPembelian.setSelectionEnd(0);
                LoadHTMLPiutang.setSelectionStart(0);
                LoadHTMLPiutang.setSelectionEnd(0);
            }
        }
    }//GEN-LAST:event_BtnCari1ActionPerformed

