    private void TCariKategoriKeyPressed(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_TCariKategoriKeyPressed
        if (evt.getKeyCode() == KeyEvent.VK_ENTER) {
            if (TCariKategori.getText().equals("")) {
                BtnCari1ActionPerformed(null);
                tampilKategoriKosong();
            } else {
                BtnCari1ActionPerformed(null);
                tampilKategori();
            }
        }
    }//GEN-LAST:event_TCariKategoriKeyPressed

