    private void ppSuratKontrolBtnPrintActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_ppSuratKontrolBtnPrintActionPerformed
        if (tabModeRegistrasi.getRowCount() == 0) {
            JOptionPane.showMessageDialog(this, "Maaf, table masih kosong...!!!!");
        } else {
            if (tbRegistrasi.getSelectedRow() != -1) {
                try {
                    pskasir = koneksi.prepareStatement("select no_sep,no_kartu,tanggal_lahir,jkel,nmdiagnosaawal from bridging_sep where no_rawat=? order by 1 desc limit 1");
                    try {
                        pskasir.setString(1, tbRegistrasi.getValueAt(tbRegistrasi.getSelectedRow(), 1).toString());
                        rskasir = pskasir.executeQuery();
                        if (rskasir.next()) {
                            this.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
                            BPJSSuratKontrol form = new BPJSSuratKontrol(null, true);
                            form.setNoRm(tbRegistrasi.getValueAt(tbRegistrasi.getSelectedRow(), 1).toString(), rskasir.getString("no_sep"), rskasir.getString("no_kartu"), NoRM.getText(), NmPasien.getText(), rskasir.getString("tanggal_lahir"), rskasir.getString("jkel"), rskasir.getString("nmdiagnosaawal"));
                            form.setSize(internalFrameRiwayatPasien.getWidth() - 20, internalFrameRiwayatPasien.getHeight() - 20);
                            form.setLocationRelativeTo(internalFrameRiwayatPasien);
                            form.setVisible(true);
                            this.setCursor(Cursor.getDefaultCursor());
                        } else {
                            JOptionPane.showMessageDialog(this, "Pasien tersebut belum terbit SEP, silahkan hubungi bagian terkait..!!");

                        }
                    } catch (Exception e) {
                        System.out.println("Notif : " + e);
                    } finally {
                        if (rskasir != null) {
                            rskasir.close();
                        }
                        if (pskasir != null) {
                            pskasir.close();
                        }
                    }
                } catch (Exception e) {
                    System.out.println("Notif : " + e);
                }
            }
        }
    }//GEN-LAST:event_ppSuratKontrolBtnPrintActionPerformed

    private void ppEdukasiMultidisiplinActionPerformed(java.awt.event.ActionEvent evt) {
        if (tbRegistrasi.getSelectedRow() != -1) {
            String norawat = tbRegistrasi.getValueAt(tbRegistrasi.getSelectedRow(), 1).toString();
            try {
                PreparedStatement ps = koneksi.prepareStatement("select * from catatan_edukasi_multidisiplin where no_rawat=?");
                ps.setString(1, norawat);
                ResultSet rs = ps.executeQuery();
                if (rs.next()) {
                    String ttdPenerima = simpanDanAmbilUrlTtd(rs.getString("signature_penerima"), "edu_penerima", norawat);
                    String ttdEdukator = ""; // signature_edukator if available

                    Map<String, Object> param = new HashMap<>();
                    param.put("namars", akses.getnamars());
                    param.put("alamatrs", akses.getalamatrs());
                    param.put("kotars", akses.getkabupatenrs());
                    param.put("propinsirs", akses.getpropinsirs());
                    param.put("kontakrs", akses.getkontakrs());
                    param.put("emailrs", akses.getemailrs());
                    param.put("logo", Sequel.cariGambar("select setting.logo from setting"));
                    param.put("no_rawat", norawat);
                    param.put("signature_penerima", ttdPenerima);
                    param.put("signature_edukator", ttdEdukator);

                    Valid.MyReport2("rptEdukasiMultidisiplin.jasper", "report", "::[ Lembar Edukasi Pasien Multidisiplin ]::", param);
                } else {
                    JOptionPane.showMessageDialog(null, "Data Edukasi Pasien Multidisiplin belum diisi untuk no rawat ini!");
                }
                rs.close();
                ps.close();
            } catch (Exception e) {
                System.out.println("Notif Print Edukasi Multidisiplin: " + e);
            }
        } else {
            JOptionPane.showMessageDialog(null, "Silahkan pilih data pasien pada tabel terlebih dahulu!");
        }
    }

