    public void setNoRm(String norm, String nama) {
        NoRM.setText(norm);
        NmPasien.setText(nama);
        isPasien();
        BtnCari1ActionPerformed(null);
        setFormMenuHeight();
    }

    public void setNoRmTengah(String norm, String nama) {
        NoRM.setText(norm);
        NmPasien.setText(nama);
        isPasien();
        BtnCari1ActionPerformed(null);
        TabRawat.setSelectedIndex(2);
        ChkAccor.setSelected(true);
        ChkAccorActionPerformed(null);
        setFormMenuHeight();
    }

    private void setFormMenuHeight() {
        int visibleCount = 0;
        for (Component comp : FormMenu.getComponents()) {
            if (comp.isVisible()) {
                visibleCount++;
            }
        }

        FormMenu.setPreferredSize(new Dimension(275, ((visibleCount * 24) + 10)));
    }

