    private void isMenu() {
        if (ChkAccor.isSelected() == true) {
            ChkAccor.setVisible(false);
            PanelAccor.setPreferredSize(new Dimension(250, HEIGHT));
            FormMenu.setVisible(true);
            ChkAccor.setVisible(true);
        } else if (ChkAccor.isSelected() == false) {
            ChkAccor.setVisible(false);
            PanelAccor.setPreferredSize(new Dimension(15, HEIGHT));
            FormMenu.setVisible(false);
            ChkAccor.setVisible(true);
        }
    }

    private void initializeProgressPanel() {
        panelProgress = new javax.swing.JPanel();
        panelProgress.setLayout(new java.awt.BorderLayout());
        // FlatLaf style: Use information/warning panel colors
        panelProgress.setBackground(new Color(255, 243, 208)); // Light yellow background (FlatLaf warning style)
        panelProgress.setBorder(javax.swing.BorderFactory.createCompoundBorder(
                javax.swing.BorderFactory.createLineBorder(new Color(255, 193, 7), 1), // FlatLaf warning border
                javax.swing.BorderFactory.createEmptyBorder(2, 2, 2, 2)
        ));
        panelProgress.setPreferredSize(new Dimension(getWidth(), 45));
        panelProgress.setVisible(false);
        panelProgress.setName("panelProgress");
        panelProgress.setOpaque(true);
        panelProgress.setMaximumSize(new Dimension(Integer.MAX_VALUE, 45));

        lblProgressMessage = new javax.swing.JLabel();
        lblProgressMessage.setFont(new java.awt.Font("Roboto", 0, 13)); // FlatLaf uses regular weight
        lblProgressMessage.setForeground(new Color(102, 51, 0)); // Dark brown text for contrast
        lblProgressMessage.setHorizontalAlignment(javax.swing.SwingConstants.CENTER);
        lblProgressMessage.setText("Memuat data riwayat perawatan...");
        lblProgressMessage.setBorder(javax.swing.BorderFactory.createEmptyBorder(0, 15, 0, 15));
        lblProgressMessage.setOpaque(false);

        progressBar = new javax.swing.JProgressBar();
        progressBar.setIndeterminate(true);
        progressBar.setPreferredSize(new Dimension(180, 22));
        progressBar.setOpaque(false);
        // FlatLaf style: Use modern progress bar styling
        progressBar.setBorder(javax.swing.BorderFactory.createEmptyBorder(1, 1, 1, 1));

        javax.swing.JPanel centerPanel = new javax.swing.JPanel();
        centerPanel.setLayout(new java.awt.FlowLayout(java.awt.FlowLayout.CENTER, 15, 12));
        centerPanel.setOpaque(false);
        centerPanel.add(lblProgressMessage);
        centerPanel.add(progressBar);

        panelProgress.add(centerPanel, java.awt.BorderLayout.CENTER);

        // Create a wrapper panel for PAGE_END that contains both progress and button panel
        // First, remove panelGlass5 from PAGE_END
        internalFrameRiwayatPasien.remove(panelGlass5);

        // Create wrapper
        javax.swing.JPanel pageEndWrapper = new javax.swing.JPanel();
        pageEndWrapper.setLayout(new java.awt.BorderLayout());
        pageEndWrapper.setOpaque(false);
        pageEndWrapper.add(panelProgress, java.awt.BorderLayout.NORTH);
        pageEndWrapper.add(panelGlass5, java.awt.BorderLayout.CENTER);

        // Add wrapper to PAGE_END
        internalFrameRiwayatPasien.add(pageEndWrapper, java.awt.BorderLayout.PAGE_END);
        internalFrameRiwayatPasien.revalidate();
        internalFrameRiwayatPasien.repaint();
    }

    private void showProgress(String message) {
        SwingUtilities.invokeLater(() -> {
            if (panelProgress != null) {
                lblProgressMessage.setText(message);
                progressBar.setIndeterminate(true);
                panelProgress.setVisible(true);
                panelProgress.setPreferredSize(new Dimension(getWidth(), 45));
                panelProgress.setMaximumSize(new Dimension(Integer.MAX_VALUE, 45));
                panelProgress.revalidate();
                panelProgress.repaint();
                panelProgress.getParent().revalidate();
                panelProgress.getParent().repaint();
            }
        });
    }

    private void updateProgress(String message) {
        SwingUtilities.invokeLater(() -> {
            if (lblProgressMessage != null) {
                lblProgressMessage.setText(message);
            }
        });
    }

    private void hideProgress() {
        SwingUtilities.invokeLater(() -> {
            if (panelProgress != null) {
                panelProgress.setVisible(false);
                panelProgress.revalidate();
                panelProgress.repaint();
            }
        });
    }

