    /**
     * Refactored tampilSatuSehat method to fetch SmartHealth Link read-only URL
     * and render it directly in JavaFX WebView inside internalFrame3
     */
    private void tampilSatuSehat() {
        if (isLoadingSatuSehat) {
            JOptionPane.showMessageDialog(this,
                    "Sedang memuat data Satu Sehat, mohon tunggu...",
                    "Info",
                    JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        if (currentSatuSehatWorker != null && !currentSatuSehatWorker.isDone()) {
            currentSatuSehatWorker.cancel(true);
            try {
                currentSatuSehatWorker.get(500, TimeUnit.MILLISECONDS);
            } catch (Exception e) {
                // Timeout or cancellation - acceptable
            }
        }

        final String noRM = NoRM.getText();
        final String userKode = akses.getkode();

        showProgress("Memuat data Satu Sehat...");

        SwingWorker<String, String> worker = new SwingWorker<String, String>() {
            private long startTime = 0;

            @Override
            protected String doInBackground() throws Exception {
                startTime = System.currentTimeMillis();

                try {
                    if (isCancelled()) {
                        return "";
                    }

                    publish("Memeriksa data NIK dan Praktisi...");

                    SatuSehatCekNIK cekNIK = new SatuSehatCekNIK();

                    // 1. Practitioner lookup using akses.getkode() and pegawai table
                    String practitionerNik = Sequel.cariIsi("select no_ktp from pegawai where nik='" + userKode + "'");
                    if (practitionerNik.equals("")) {
                        practitionerNik = userKode;
                    }
                    String practitionerName = Sequel.cariIsi("select nama from pegawai where nik='" + userKode + "'");
                    String practitionerIhs = "";
                    if (!practitionerNik.equals("")) {
                        try {
                            practitionerIhs = cekNIK.tampilIDParktisi(practitionerNik);
                        } catch (Exception ex) {
                            System.out.println("Gagal query IHS Praktisi: " + ex);
                        }
                    }
                    if (practitionerIhs.equals("")) {
                        practitionerIhs = Sequel.cariIsi("select ihspegawai from satu_sehat_ihs_practitioner where nikpegawai='" + practitionerNik + "'");
                    }

                    if (isCancelled()) {
                        return "";
                    }

                    publish("Memeriksa data IHS Pasien...");

                    // 2. Patient lookup using NoRM
                    String patientNik = Sequel.cariIsi("select no_ktp from pasien where no_rkm_medis='" + noRM + "'");
                    String patientName = Sequel.cariIsi("select nm_pasien from pasien where no_rkm_medis='" + noRM + "'");
                    String patientIhs = "";
                    if (!patientNik.equals("")) {
                        try {
                            patientIhs = cekNIK.tampilIDPasien(patientNik);
                        } catch (Exception ex) {
                            System.out.println("Gagal query IHS Pasien: " + ex);
                        }
                    }
                    if (patientIhs.equals("")) {
                        patientIhs = Sequel.cariIsi("select ihspasien from satu_sehat_ihs_patient where nikpasien='" + patientNik + "'");
                    }

                    if (isCancelled()) {
                        return "";
                    }

                    // 3. Organization info
                    String orgId = koneksiDB.IDSATUSEHAT();
                    String orgName = akses.getnamars();

                    currentSatuSehatPatientName = patientName;
                    currentSatuSehatPatientIhs = patientIhs;
                    currentSatuSehatPractitionerName = practitionerName;
                    currentSatuSehatPractitionerIhs = practitionerIhs;

                    publish("Mengambil SmartHealth Link dari Satu Sehat (NTL v2)...");

                    ApiSatuSehat apiSS = new ApiSatuSehat();
                    String shlUrl = apiSS.getSmartHealthLink(patientIhs, patientName, practitionerIhs, practitionerName, orgId, orgName);
                    String statusMsg = apiSS.getLastStatusMessage();
                    if (statusMsg != null && !statusMsg.isEmpty()) {
                        publish(statusMsg);
                    }

                    long duration = System.currentTimeMillis() - startTime;
                    publish("Data berhasil diproses dalam " + (duration / 1000) + " detik");

                    return shlUrl;

                } catch (Exception e) {
                    System.out.println("Error tampilSatuSehat: " + e);
                    e.printStackTrace();
                    return "<html><body style='text-align:center; padding:50px; color:red;'>"
                            + "<h3>Gagal Memuat Data Satu Sehat</h3>"
                            + "<p>Error: " + e.getMessage() + "</p>"
                            + "</body></html>";
                }
            }

            @Override
            protected void process(List<String> chunks) {
                if (!chunks.isEmpty()) {
                    String lastMessage = chunks.get(chunks.size() - 1);
                    updateProgress(lastMessage);
                }
            }

            @Override
            protected void done() {
                isLoadingSatuSehat = false;
                hideProgress();

                try {
                    if (!isCancelled()) {
                        String resultUrlOrHtml = get();
                        currentSatuSehatUrl = resultUrlOrHtml != null ? resultUrlOrHtml : "";
                        if (resultUrlOrHtml != null && !resultUrlOrHtml.isEmpty()) {
                            if (resultUrlOrHtml.contains("consent") || resultUrlOrHtml.contains("launch=")) {
                                currentSatuSehatStatusType = "CONSENT_VERIFICATION";
                                if (lblStatusSatuSehat != null) {
                                    lblStatusSatuSehat.setForeground(new java.awt.Color(200, 80, 0));
                                    lblStatusSatuSehat.setText("Status: Memerlukan Persetujuan (Gunakan Opsi A Kode SSM / Opsi C Akses Darurat)");
                                }
                            } else if (resultUrlOrHtml.startsWith("http://") || resultUrlOrHtml.startsWith("https://")) {
                                currentSatuSehatStatusType = "ACTIVE_RME";
                                if (lblStatusSatuSehat != null) {
                                    lblStatusSatuSehat.setForeground(new java.awt.Color(0, 120, 50));
                                    lblStatusSatuSehat.setText("Status: Rekam Medis Nasional Aktif");
                                }
                            } else {
                                currentSatuSehatStatusType = "ERROR";
                                if (lblStatusSatuSehat != null) {
                                    lblStatusSatuSehat.setForeground(java.awt.Color.RED);
                                    lblStatusSatuSehat.setText("Status: Gagal memuat data Satu Sehat");
                                }
                            }
                            loadURLSatuSehat(resultUrlOrHtml);
                            if (resultUrlOrHtml.startsWith("http://") || resultUrlOrHtml.startsWith("https://")) {
                                bukaSatuSehatAppMode(resultUrlOrHtml);
                            }
                        } else {
                            currentSatuSehatStatusType = "ERROR";
                            if (lblStatusSatuSehat != null) {
                                lblStatusSatuSehat.setForeground(java.awt.Color.RED);
                                lblStatusSatuSehat.setText("Status: URL Satu Sehat tidak diperoleh");
                            }
                            fallbackToEditorPaneSatuSehat("<html><body style='text-align:center; padding:50px; color:red;'>"
                                    + "<h3>URL Satu Sehat Tidak Ditemukan</h3>"
                                    + "<p>Gagal memperoleh SmartHealth Link dari server Satu Sehat. Pastikan IHS Pasien dan IHS Praktisi terdaftar.</p>"
                                    + "</body></html>");
                        }
                    }
                } catch (CancellationException e) {
                    // Cancelled
                } catch (Exception e) {
                    System.out.println("Error in done(): " + e);
                    fallbackToEditorPaneSatuSehat("<html><body style='text-align:center; padding:50px; color:red;'>"
                            + "<h3>Gagal Memuat Data</h3>"
                            + "<p>Error: " + e.getMessage() + "</p>"
                            + "</body></html>");
                } finally {
                    if (currentSatuSehatWorker == this) {
                        currentSatuSehatWorker = null;
                    }
                }
            }
        };

        isLoadingSatuSehat = true;
        currentSatuSehatWorker = worker;
        worker.execute();
    }

    /**
     * Buka URL Satu Sehat aktif di Browser (Chrome App-Mode / Window Mandiri)
     */
    private void bukaSatuSehatExternalBrowser() {
        bukaSatuSehatAppMode(currentSatuSehatUrl);
    }

    /**
     * Meluncurkan Chrome / Edge dalam Application Mode (Jendela Mandiri tanpa
     * tab & URL bar)
     */
    private void bukaSatuSehatAppMode(String url) {
        if (url == null || url.trim().isEmpty() || (!url.startsWith("http://") && !url.startsWith("https://"))) {
            JOptionPane.showMessageDialog(this, "URL Satu Sehat belum tersedia. Silakan klik 'Muat Ulang RME' terlebih dahulu.", "Informasi", JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        boolean launched = false;
        String os = System.getProperty("os.name").toLowerCase();

        try {
            if (os.contains("win")) {
                // Windows: Chrome App Mode -> Edge App Mode
                String[] commands = new String[]{
                    "cmd /c start chrome --app=\"" + url + "\" --window-size=1280,850",
                    "cmd /c start msedge --app=\"" + url + "\" --window-size=1280,850"
                };
                for (String cmd : commands) {
                    try {
                        Process p = Runtime.getRuntime().exec(cmd);
                        if (p != null) {
                            launched = true;
                            break;
                        }
                    } catch (Exception e) {
                    }
                }
            } else if (os.contains("mac")) {
                // macOS
                try {
                    Process p = Runtime.getRuntime().exec(new String[]{"open", "-a", "Google Chrome", "--args", "--app=" + url});
                    launched = (p != null);
                } catch (Exception e) {
                }
            } else {
                // Linux / Unix: Google Chrome / Chromium App Mode
                String[] chromeExecs = new String[]{"google-chrome", "google-chrome-stable", "chromium-browser", "chromium"};
                for (String exec : chromeExecs) {
                    try {
                        Process p = new ProcessBuilder(exec, "--app=" + url, "--window-size=1280,850").start();
                        if (p != null) {
                            launched = true;
                            break;
                        }
                    } catch (Exception e) {
                    }
                }
            }
        } catch (Exception ex) {
            System.err.println("Gagal meluncurkan browser App Mode: " + ex);
        }

        // Fallback jika mode App tidak berhasil: Buka di browser standar OS
        if (!launched) {
            try {
                if (java.awt.Desktop.isDesktopSupported() && java.awt.Desktop.getDesktop().isSupported(java.awt.Desktop.Action.BROWSE)) {
                    java.awt.Desktop.getDesktop().browse(new java.net.URI(url));
                } else {
                    Runtime.getRuntime().exec("xdg-open " + url);
                }
            } catch (Exception ex) {
                System.err.println("Gagal membuka browser fallback: " + ex);
                JOptionPane.showMessageDialog(this, "Gagal membuka browser: " + ex.getMessage(), "Peringatan", JOptionPane.WARNING_MESSAGE);
            }
        }
    }

