    private void createSceneSatuSehat() {
        Platform.runLater(new Runnable() {
            @Override
            public void run() {
                WebView view = new WebView();

                engineSatuSehat = view.getEngine();
                engineSatuSehat.setJavaScriptEnabled(true);

                engineSatuSehat.setCreatePopupHandler(new Callback<PopupFeatures, WebEngine>() {
                    @Override
                    public WebEngine call(PopupFeatures p) {
                        Stage stage = new Stage(StageStyle.TRANSPARENT);
                        return view.getEngine();
                    }
                });

                // Tangkap klik tautan aksi (action:launch) dari HTML dashboard
                engineSatuSehat.locationProperty().addListener((ObservableValue<? extends String> ov, String oldValue, final String newValue) -> {
                    if (newValue != null && newValue.contains("action:launch")) {
                        SwingUtilities.invokeLater(() -> {
                            bukaSatuSehatAppMode(currentSatuSehatUrl);
                        });
                    }
                });

                engineSatuSehat.getLoadWorker().exceptionProperty().addListener((ObservableValue<? extends Throwable> o, Throwable old, final Throwable value) -> {
                    if (engineSatuSehat.getLoadWorker().getState() == Worker.State.FAILED) {
                        SwingUtilities.invokeLater(() -> {
                            System.err.println("Gagal memuat URL SatuSehat: " + (value != null ? value.getMessage() : "Unknown"));
                        });
                    }
                });

                fxPanelSatuSehat.setScene(new Scene(view));
            }
        });
    }

    public void loadURLSatuSehat(String url) {
        try {
            createSceneSatuSehat();
        } catch (Exception e) {
            System.err.println("Error createSceneSatuSehat: " + e);
        }

        Platform.runLater(() -> {
            try {
                if (engineSatuSehat != null) {
                    if (url.startsWith("http://") || url.startsWith("https://")) {
                        String dashboardHtml = generateSatuSehatDashboardHtml(url, currentSatuSehatStatusType);
                        engineSatuSehat.loadContent(dashboardHtml);
                    } else {
                        engineSatuSehat.loadContent(url);
                    }
                }
            } catch (Exception exception) {
                System.err.println("Error loadURLSatuSehat: " + exception);
            }
        });
    }

    /**
     * Fallback to JEditorPane for Satu Sehat
     */
    private void fallbackToEditorPaneSatuSehat(String urlOrHtml) {
        try {
            JEditorPane editorPane;
            if (urlOrHtml.startsWith("http://") || urlOrHtml.startsWith("https://")) {
                editorPane = new JEditorPane("text/html", "<html><body style='font-family:sans-serif; text-align:center; padding:50px;'>"
                        + "<h2>SatuSehat SmartHealth Link</h2>"
                        + "<p>URL: <a href='" + urlOrHtml + "'>" + urlOrHtml + "</a></p>"
                        + "<p style='margin-top:20px;'><a href='#' style='font-size:14px; color:#0066cc;'>Gunakan tombol 'Buka di Browser' di atas untuk mengakses RME</a></p>"
                        + "</body></html>");
            } else {
                editorPane = new JEditorPane("text/html", urlOrHtml);
            }
            editorPane.setEditable(false);
            editorPane.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);

            JScrollPane scrollPane = new JScrollPane(editorPane);
            scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
            scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);

            PanelSatuSehatWebView.removeAll();
            PanelSatuSehatWebView.setLayout(new BorderLayout());
            PanelSatuSehatWebView.add(scrollPane, BorderLayout.CENTER);
            PanelSatuSehatWebView.revalidate();
            PanelSatuSehatWebView.repaint();
        } catch (Exception e) {
            System.err.println("Kesalahan fallback EditorPane SatuSehat: " + e.getMessage());
        }
    }

