    private void tampilPRMPRJ() {
        try {
            htmlContent = new StringBuilder();
            try {
                rs3 = koneksi.prepareStatement(
                        "SELECT\n"
                        + "	prmpj_rajal.no_rawat,\n"
                        + "	reg_periksa.no_rkm_medis,\n"
                        + "	pasien.nm_pasien,\n"
                        + "	reg_periksa.tgl_registrasi,\n"
                        + "	reg_periksa.jam_reg,\n"
                        + "	prmpj_rajal.kd_dokter,\n"
                        + "	dokter.nm_dokter,\n"
                        + "	prmpj_rajal.diagnosapenting,\n"
                        + "	prmpj_rajal.uraianklinis,\n"
                        + "	prmpj_rajal.rencanapenting,\n"
                        + "	prmpj_rajal.catatanpenting \n"
                        + "FROM\n"
                        + "	reg_periksa\n"
                        + "	INNER JOIN dokter\n"
                        + "	INNER JOIN prmpj_rajal ON dokter.kd_dokter = prmpj_rajal.kd_dokter \n"
                        + "	AND reg_periksa.no_rawat = prmpj_rajal.no_rawat\n"
                        + "	INNER JOIN pasien ON prmpj_rajal.no_rkm_medis = pasien.no_rkm_medis \n"
                        + "WHERE\n"
                        + "	prmpj_rajal.no_rkm_medis = '" + NoRM.getText() + "' order by prmpj_rajal.no_rawat desc").executeQuery();
                if (rs3.next()) {
                    htmlContent.append(
                            "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0' class='tbl_form'>"
                            + "<tr class='isi'>"
                            + "<td valign='top' width='10%' align='center' bgcolor='#a7fac3'>Waktu Kunjungan.</td>"
                            + "<td valign='top' width='10%' align='center' bgcolor='#a7fac3'>Dokter Spesialis</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Diagnosa Penting</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Uraian Klinis Penting</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Rencana Penting</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Catatan Penting</td>"
                            + "</tr>");
                    rs3.beforeFirst();
                    w = 1;
                    while (rs3.next()) {
                        htmlContent.append(
                                "<tr class='isi'>"
                                + "<td valign='top' width='10%' align='justify' >" + rs3.getString("tgl_registrasi") + " " + rs3.getString("jam_reg") + "</td>"
                                + "<td valign='top' width='10%' align='justify' >" + rs3.getString("nm_dokter") + "</td>"
                                + "<td valign='top' width='20%' align='justify' >" + rs3.getString("diagnosapenting") + "</td>"
                                + "<td valign='top' width='20%' align='justify' >" + rs3.getString("uraianklinis") + "</td>"
                                + "<td valign='top' width='20%' align='justify' >" + rs3.getString("rencanapenting") + "</td>"
                                + "<td valign='top' width='20%' align='justify' >" + rs3.getString("catatanpenting") + "</td>"
                                + "</tr>");
                        w++;
                    }
                    htmlContent.append(
                            "</table>");
                } else {
                    htmlContent.append(
                            "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0' class='tbl_form'>"
                            + "<tr class='isi'>"
                            + "<td valign='top' width='10%' align='center' bgcolor='#a7fac3'>Waktu Kunjungan.</td>"
                            + "<td valign='top' width='10%' align='center' bgcolor='#a7fac3'>Dokter Spesialis</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Diagnosa Penting</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Uraian Klinis Penting</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Rencana Penting</td>"
                            + "<td valign='top' width='20%' align='center' bgcolor='#a7fac3'>Catatan Penting</td>"
                            + "</tr>"
                            + "</table>");
                }
            } catch (Exception e) {
                System.out.println("Notifikasi : " + e);
            } finally {
                if (rs3 != null) {
                    rs3.close();
                }
            }
            LoadHTMLPRMPRJ.setText("<html>" + htmlContent.toString() + "</html>");
        } catch (Exception e) {
            System.out.println("Notifikasi : " + e);
        }
    }

