    private void menampilkanLaporanPersalinan(String norawat) {
        try {
            if (chkAsuhanMedisRanapKandungan.isSelected() == true) {
                try {
                    rs2 = koneksi.prepareStatement(
                            "SELECT\n"
                            + "	reg_periksa.no_rkm_medis, \n"
                            + "	dokter.nm_dokter, \n"
                            + "	catatan_laporan_persalinan.catatan\n"
                            + "FROM\n"
                            + "	dokter\n"
                            + "	INNER JOIN\n"
                            + "	reg_periksa\n"
                            + "	ON \n"
                            + "		dokter.kd_dokter = reg_periksa.kd_dokter\n"
                            + "	INNER JOIN\n"
                            + "	catatan_laporan_persalinan\n"
                            + "	ON \n"
                            + "		catatan_laporan_persalinan.no_rawat = reg_periksa.no_rawat "
                            + "where catatan_laporan_persalinan.no_rawat='" + norawat + "'").executeQuery();
                    if (rs2.next()) {
                        htmlContent.append(
                                "<tr class='isi'>"
                                + "<td valign='top' width='2%'></td>"
                                + "<td valign='top' width='18%'></td>"
                                + "<td valign='top' width='1%' align='center'>:</td>"
                                + "<td valign='top' width='79%'>"
                                + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                                + "<tr>"
                                + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>Laporan Persalinan</td>\n"
                                + "</tr>"
                                + "</table>"
                                + "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0' class='tbl_form'>"
                        );
                        rs2.beforeFirst();
                        while (rs2.next()) {
                            htmlContent.append(
                                    "<tr>"
                                    + "<td valign='top'>"
                                    + "YANG MELAKUKAN PENGKAJIAN"
                                    + "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0px' class='tbl_form'>"
                                    + "<tr>"
                                    + "<td width='33%' border='0'>Dokter : " + rs2.getString("nm_dokter") + "</td>"
                                    + "</tr>"
                                    + "</table>"
                                    + "</td>"
                                    + "</tr>"
                                    + "<tr>"
                                    + "<td valign='top'>"
                                    + "I. Laporan Persalinan"
                                    + "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0px' class='tbl_form'>"
                                    + "<tr>"
                                    + "<td colspan='2'>Laporan Persalinan : " + rs2.getString("catatan").replaceAll("(\r\n|\r|\n|\n\r)", "<br>") + "</td>"
                                    + "</tr>"
                                    + "</table>"
                                    + "</td>"
                                    + "</tr>");
                        }
                        htmlContent.append(
                                "</table>"
                                + "</td>"
                                + "</tr>");
                    }
                } catch (Exception e) {
                    System.out.println("Notifikasi : " + e);
                } finally {
                    if (rs2 != null) {
                        rs2.close();
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Notif Laporan Persalinan : " + e);
        }
    }

