                        String ttdDokterUrl = simpanDanAmbilUrlTtd(rs2.getString("ttd_dokter"), "sto_dokter", norawat);

                        String imgTtdPasien = sigImgHtml(ttdPasienUrl, "60", "30");
                        String imgTtdFarmasi = sigImgHtml(ttdFarmasiUrl, "60", "30");
