    private void menampilkanVaksinPasien(String norawat) {
        try {
            if (chkVaksinPasien.isSelected() == true) {

                try {
                    rs2 = koneksi.prepareStatement(
                            "SELECT\n"
                            + "	vaksin.no_rawat, \n"
                            + "	reg_periksa.no_rkm_medis, \n"
                            + "	pasien.nm_pasien, \n"
                            + "	pasien.jk, \n"
                            + "	TIMESTAMPDIFF(YEAR, pasien.tgl_lahir, CURDATE()) AS umur, \n"
                            + "	pasien.no_tlp, \n"
                            + "	penjab.png_jawab, \n"
                            + "	satu_sehat_ref_vaksincode.display, \n"
                            + "	vaksin.no_batch, \n"
                            + "	vaksin.programkode, \n"
                            + "	vaksin.programdisplay, \n"
                            + "	vaksin.programjns, "
                            + " vaksin.tgl_perawatan as tanggalvaksin,\n"
                            + "	vaksin.programproto, \n"
                            + "	vaksin.nippetugas,vaksin.nopasspor, \n"
                            + "	pegawai.nama\n"
                            + " FROM\n"
                            + "	reg_periksa\n"
                            + "	INNER JOIN\n"
                            + "	penjab\n"
                            + "	ON \n"
                            + "		reg_periksa.kd_pj = penjab.kd_pj\n"
                            + "	INNER JOIN\n"
                            + "	pasien\n"
                            + "	ON \n"
                            + "		reg_periksa.no_rkm_medis = pasien.no_rkm_medis\n"
                            + "	INNER JOIN\n"
                            + "	vaksin\n"
                            + "	ON \n"
                            + "		reg_periksa.no_rawat = vaksin.no_rawat\n"
                            + "	INNER JOIN\n"
                            + "	satu_sehat_ref_vaksincode\n"
                            + "	ON \n"
                            + "		vaksin.vaksincode = satu_sehat_ref_vaksincode.kode\n"
                            + "	INNER JOIN\n"
                            + "	pegawai\n"
                            + "	ON \n"
                            + "		vaksin.nippetugas = pegawai.nik "
                            + "where vaksin.no_rawat='" + norawat + "'").executeQuery();
                    if (rs2.next()) {
                        htmlContent.append(
                                "<tr class='isi'>"
                                + "<td valign='top' width='2%'></td>"
                                + "<td valign='top' width='18%'></td>"
                                + "<td valign='top' width='1%' align='center'>:</td>"
                                + "<td valign='top' width='79%'>"
                                + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                                + "<tr>"
                                + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>Riwayat Vaksin Pasien</td>\n"
                                + "</tr>"
                                + "</table>"
                                + "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='5%'>No</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>Tanggal</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>Vaksin</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>No Batch</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>No Passpor</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>PROGRAM</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>JENIS</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='30%'>PROTOKOL</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='15%'>Asesmen oleh</td>"
                                + "</tr>"
                        );
//                        "No.Rawat", "No.RM", "Nama Pasien", "J.K.", "Umur", "No.Telp", "Cara Bayar", "Vaksin", "NO BATCH", "PROGRAM", "NAMA PROGRAM", "JENIS", "PROTOKOL", "NIP", "Nama Petugas", "No Passpor"
                        rs2.beforeFirst();
                        int nomoralergi = 0;
                        while (rs2.next()) {
                            nomoralergi++;
                            htmlContent.append(
                                    "<tr>"
                                    + "<td valign='middle' align='left' width='5%'>" + nomoralergi + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("tanggalvaksin") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("display") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("no_batch") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("nopasspor") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("programdisplay") + "</td>"
                                    + "<td valign='middle' align='left' width='30%'>" + rs2.getString("programjns") + "</td>"
                                    + "<td valign='middle' align='left' width='15%'>" + rs2.getString("programproto") + "</td>"
                                    + "<td valign='middle' align='left' width='15%'>" + rs2.getString("nama") + "</td>"
                                    + "</tr>"
                            );
                        }
                        htmlContent.append(
                                "</table>"
                                + "</td>"
                                + "</tr>");
                    }
                } catch (Exception e) {
                    System.out.println("Notifikasi : " + e);
                } finally {
                    if (rs2 != null) {
                        rs2.close();
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Notif Vaksin : " + e);
        }
    }

