    private void menampilkanBerkasDigitalDariPDF(String norawat) {
        try {
            if (!chkBerkasDigital.isSelected()) {
                return;
            }

            String query = "SELECT master_berkas_digital.nama, berkas_digital_perawatan.lokasi_file "
                    + "FROM berkas_digital_perawatan "
                    + "INNER JOIN master_berkas_digital ON berkas_digital_perawatan.kode = master_berkas_digital.kode "
                    + "WHERE berkas_digital_perawatan.no_rawat = ?";

            try (PreparedStatement ps = koneksi.prepareStatement(query)) {
                ps.setString(1, norawat);

                try (ResultSet rs2 = ps.executeQuery()) {
                    if (!rs2.isBeforeFirst()) {
                        return;
                    }

                    // Build HTML header
                    htmlContent.append(
                            "<tr class='isi'>"
                            + "<td valign='top' width='2%'></td>"
                            + "<td valign='top' width='18%' style='font-weight: bold; color: black;'></td>"
                            + "<td valign='top' width='1%' align='center'>:</td>"
                            + "<td valign='top' width='79%'>"
                            + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>"
                            + "<tr><td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>"
                            + "Berkas Digital Perawatan Pasien</td></tr>"
                            + "</table>"
                    );

                    // Process PDFs with 96 DPI (optimized resolution matching target 800px display width)
                    List<PdfDocumentData> pdfDocuments = processPdfDocuments(rs2, norawat, 96f);

                    if (!pdfDocuments.isEmpty()) {
                        for (PdfDocumentData docData : pdfDocuments) {
                            if (docData.imagePaths != null && !docData.imagePaths.isEmpty()) {
                                String pdfHtml = generatePdfImagesHtml(
                                        docData.fileName,
                                        docData.pdfUrl,
                                        docData.imagePaths
                                );
                                htmlContent.append(pdfHtml);
                            } else {
                                // Fallback if PDF couldn't be processed
                                htmlContent.append("<table width='100%' border='0' cellspacing='0' cellpadding='10' style='margin-bottom:15px;'>");
                                htmlContent.append("<tr><td align='center' style='background-color:#fff3cd; border:2px solid #ffc107; padding:15px;'>");
                                htmlContent.append("<strong style='color:#856404;'>⚠ Tidak dapat memproses PDF: ");
                                htmlContent.append(docData.fileName.replaceAll("pages/upload/", ""));
                                htmlContent.append("</strong><br/>");
                                htmlContent.append("<a href='").append(docData.pdfUrl).append("' target='_blank' style='color:#007bff; text-decoration:none; margin-top:10px; display:inline-block;'>");
                                htmlContent.append("Klik di sini untuk membuka PDF di browser</a>");
                                htmlContent.append("</td></tr>");
                                htmlContent.append("</table>");
                            }
                        }
                    }

                    htmlContent.append("</td></tr>");
                }
            }

        } catch (SQLException e) {
            System.err.println("SQL Error in menampilkanBerkasDigital: " + e.getMessage());
            e.printStackTrace();
        } catch (Exception e) {
            System.err.println("General Error in menampilkanBerkasDigital: " + e.getMessage());
            e.printStackTrace();
        }
    }

