//menampilkan riwayat alergi pasien
    private void menampilkanRiwayatAlergiPasien(String norawat) {
        try {
            if (chkRiwayatAlergiPasien.isSelected() == true) {
                try {
                    rs2 = koneksi.prepareStatement(
                            "SELECT\n"
                            + "	reg_periksa.no_rawat, \n"
                            + "	reg_periksa.no_rkm_medis,\n"
                            + "	alergi_pasien.tgl_perawatan, \n"
                            + "	satu_sehat_ref_allergy.display, \n"
                            + "	alergi_pasien.category, \n"
                            + "	alergi_pasien.note, \n"
                            + "	satu_sehat_ref_allergy_reaction.display as reaksi, \n"
                            + "	alergi_pasien.severity, \n"
                            + "	pegawai.nama as petugas\n"
                            + "FROM\n"
                            + "	reg_periksa\n"
                            + "	INNER JOIN\n"
                            + "	alergi_pasien\n"
                            + "	ON \n"
                            + "		reg_periksa.no_rawat = alergi_pasien.no_rawat\n"
                            + "	INNER JOIN\n"
                            + "	satu_sehat_ref_allergy\n"
                            + "	ON \n"
                            + "		alergi_pasien.allergy_code = satu_sehat_ref_allergy.kode\n"
                            + "	INNER JOIN\n"
                            + "	pegawai\n"
                            + "	ON \n"
                            + "		alergi_pasien.nippetugas = pegawai.nik\n"
                            + "	INNER JOIN\n"
                            + "	satu_sehat_ref_allergy_reaction\n"
                            + "	ON \n"
                            + "		alergi_pasien.reactioncode = satu_sehat_ref_allergy_reaction.kode\n"
                            + "		where reg_periksa.no_rawat='" + norawat + "'\n"
                            + "		").executeQuery();
                    if (rs2.next()) {
                        htmlContent.append(
                                "<tr class='isi'>"
                                + "<td valign='top' width='2%'></td>"
                                + "<td valign='top' width='18%'></td>"
                                + "<td valign='top' width='1%' align='center'>:</td>"
                                + "<td valign='top' width='79%'>"
                                + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                                + "<tr>"
                                + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>Riwayat Alergi Pasien</td>\n"
                                + "</tr>"
                                + "</table>"
                                + "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='5%'>No</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>Tgl Asesmen</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>Alergi</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>Kategori</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>Reaksi</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='10%'>Severity</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='30%'>Catatan</td>"
                                + "<td valign='middle' bgcolor='#a7fac3' align='left' width='15%'>Asesmen oleh</td>"
                                + "</tr>"
                        );
                        rs2.beforeFirst();
                        int nomoralergi = 0;
                        while (rs2.next()) {
                            nomoralergi++;
                            htmlContent.append(
                                    "<tr>"
                                    + "<td valign='middle' align='left' width='5%'>" + nomoralergi + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("tgl_perawatan") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("display") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("category") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("reaksi") + "</td>"
                                    + "<td valign='middle' align='left' width='10%'>" + rs2.getString("severity") + "</td>"
                                    + "<td valign='middle' align='left' width='30%'>" + rs2.getString("note") + "</td>"
                                    + "<td valign='middle' align='left' width='15%'>" + rs2.getString("petugas") + "</td>"
                                    + "</tr>"
                            );
                        }
                        htmlContent.append(
                                "</table>"
                                + "</td>"
                                + "</tr>");
                    }
                } catch (Exception e) {
                    System.out.println("Notifikasi : " + e);
                } finally {
                    if (rs2 != null) {
                        rs2.close();
                    }
                }

            }
        } catch (Exception e) {
            System.out.println("Notif Riwayat Alergi Pasien : " + e);
        }
    }

