    private void tampilPenyakit(String normpasien) {
        if (Sequel.cariInteger("select count(no_rkm_medis) from pasien_penyakitmenular where no_rkm_medis='" + normpasien + "'") > 0) {
//            System.out.println("here");
            if (Sequel.cariIsi("select penyakit from pasien_penyakitmenular where no_rkm_medis='" + normpasien + "'").equals("Hbs Ag positif atau Hepatitis B")) {
                PanelWall.setBackgroundImage(new javax.swing.ImageIcon(getClass().getResource("/picture/bluelingkaran.png")));
                PanelWall.setRound(true);
//                System.out.println("hbs");
            } else if (Sequel.cariIsi("select penyakit from pasien_penyakitmenular where no_rkm_medis='" + normpasien + "'").equals("Tubercolusis")) {
                PanelWall.setBackgroundImage(new javax.swing.ImageIcon(getClass().getResource("/picture/greenlingkaran.png")));
                PanelWall.setRound(true);
//                System.out.println("tuber");
            } else if (Sequel.cariIsi("select penyakit from pasien_penyakitmenular where no_rkm_medis='" + normpasien + "'").equals("HIV/AID")) {
                PanelWall.setBackgroundImage(new javax.swing.ImageIcon(getClass().getResource("/picture/redlingkaran.png")));
                PanelWall.setRound(true);
//                System.out.println("hiv");
            } else if (Sequel.cariIsi("select penyakit from pasien_penyakitmenular where no_rkm_medis='" + normpasien + "'").equals("Penyakit Menular")) {
                PanelWall.setBackgroundImage(new javax.swing.ImageIcon(getClass().getResource("/picture/kuningkotak.png")));
                PanelWall.setRound(false);
//                System.out.println("men");
            } else {
                PanelWall.setBackgroundImage(null);
            }
        } else {
            PanelWall.setBackgroundImage(null);
        }
    }

    private void tampilJKGambar(String jkpasien) {
//        System.out.println(jkpasien);
        if (jkpasien.equals("L")) {
            PanelGender.setBackgroundImage(new javax.swing.ImageIcon(getClass().getResource("/48x48/male.png")));
            PanelGender.setRound(true);
        } else {
            PanelGender.setBackgroundImage(new javax.swing.ImageIcon(getClass().getResource("/48x48/female.png")));
            PanelGender.setRound(true);
        }
    }

