    private void tampilImagingRadiology() {
        // Prevent concurrent loading
        if (isLoadingRadiology) {
            JOptionPane.showMessageDialog(this,
                    "Sedang memuat data radiologi, mohon tunggu...",
                    "Info",
                    JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        // Cancel previous worker if still running
        if (currentRadiologyWorker != null && !currentRadiologyWorker.isDone()) {
            currentRadiologyWorker.cancel(true);
            try {
                currentRadiologyWorker.get(500, TimeUnit.MILLISECONDS);
            } catch (Exception e) {
                // Timeout or cancellation - acceptable
            }
        }

        // CRITICAL: Capture all UI values in EDT BEFORE background thread starts
        final int selectedIndex = cmbTampilkanDataBerdasarkan.getSelectedIndex();
        final String noRM = NoRM.getText();
        final String tgl1 = Valid.SetTgl(Tgl1.getSelectedItem() + "");
        final String tgl2 = Valid.SetTgl(Tgl2.getSelectedItem() + "");

        // Show loading indicator
        showProgress("Memuat data radiologi...");

        // Create SwingWorker
        SwingWorker<String, String> worker = new SwingWorker<String, String>() {
            private int totalRecords = 0;
            private int processedRecords = 0;
            private long startTime = 0;

            @Override
            protected String doInBackground() throws Exception {
                PreparedStatement ps = null;
                ResultSet rs = null;
                StringBuilder htmlContent = new StringBuilder();

                startTime = System.currentTimeMillis();

                try {
                    // Build query based on selected index
                    String query = "";

                    if (selectedIndex == 1) {
                        query = "select reg_periksa.no_reg,reg_periksa.no_rawat,reg_periksa.tgl_registrasi,reg_periksa.status_lanjut "
                                + "from reg_periksa where reg_periksa.stts<>'Batal' and reg_periksa.no_rkm_medis=? "
                                + "order by reg_periksa.tgl_registrasi desc limit 5";
                    } else if (selectedIndex == 2) {
                        query = "select reg_periksa.no_reg,reg_periksa.no_rawat,reg_periksa.tgl_registrasi,reg_periksa.status_lanjut "
                                + "from reg_periksa where reg_periksa.stts<>'Batal' and reg_periksa.no_rkm_medis=? "
                                + "order by reg_periksa.tgl_registrasi desc";
                    } else if (selectedIndex == 3) {
                        query = "select reg_periksa.no_reg,reg_periksa.no_rawat,reg_periksa.tgl_registrasi,reg_periksa.status_lanjut "
                                + "from reg_periksa where reg_periksa.stts<>'Batal' and reg_periksa.no_rkm_medis=? and "
                                + "reg_periksa.tgl_registrasi between ? and ? order by reg_periksa.tgl_registrasi desc";
                    } else if (selectedIndex == 0) {
                        query = "select reg_periksa.no_reg,reg_periksa.no_rawat,reg_periksa.tgl_registrasi,reg_periksa.status_lanjut "
                                + "from reg_periksa where reg_periksa.stts<>'Batal' and reg_periksa.no_rkm_medis=? "
                                + "order by reg_periksa.tgl_registrasi desc limit 1";
                    }

                    // Prepare statement
                    ps = koneksi.prepareStatement(query);

                    // Set parameters based on selected index
                    if (selectedIndex == 1 || selectedIndex == 2 || selectedIndex == 0) {
                        ps.setString(1, noRM);
                    } else if (selectedIndex == 3) {
                        ps.setString(1, noRM);
                        ps.setString(2, tgl1);
                        ps.setString(3, tgl2);
                    }

                    // Execute query
                    publish("Mengambil data registrasi...");
                    rs = ps.executeQuery();

                    // Count total records
                    rs.last();
                    totalRecords = rs.getRow();
                    rs.beforeFirst();

                    publish("Ditemukan " + totalRecords + " record registrasi");

                    // Process each record
                    while (rs.next()) {
                        // Check for cancellation
                        if (isCancelled()) {
                            publish("Dibatalkan oleh pengguna");
                            break;
                        }

                        processedRecords++;
                        String noRawat = rs.getString("no_rawat");
                        String tglRegistrasi = rs.getString("tgl_registrasi");
                        String statusLanjut = rs.getString("status_lanjut");

                        // Publish progress update
                        publish("Memproses " + processedRecords + "/" + totalRecords
                                + " - " + noRawat + " (" + tglRegistrasi + ")");

                        // Build HTML header for this record
                        htmlContent.append("<tr><td colspan='2' style='border-bottom: 1px solid #ccc; padding: 5px 0;'>");
                        htmlContent.append("<strong>Tanggal: </strong>").append(tglRegistrasi);
                        htmlContent.append(" | ");
                        htmlContent.append("<strong>Status: </strong>").append(statusLanjut);
                        htmlContent.append("</td></tr>");

                        // Generate radiology content (HEAVY PART - multiple queries + API calls)
                        try {
                            publish("Memuat data radiologi untuk " + noRawat + "...");

                            // This method contains multiple database queries and potentially slow API calls
                            StringBuilder radiologyContent = tampilImagingRadiologiPublik(noRawat);
                            htmlContent.append(radiologyContent.toString());
                            htmlContent.append("<br>");

                        } catch (Exception e) {
                            System.out.println("Error loading radiology for " + noRawat + ": " + e);
                            htmlContent.append("<tr><td colspan='2' style='color: red; padding: 10px;'>");
                            htmlContent.append("Error memuat data radiologi: ").append(e.getMessage());
                            htmlContent.append("</td></tr>");
                        }

                        // Small pause to prevent overwhelming the API
                        if (processedRecords < totalRecords) {
                            Thread.sleep(100); // 100ms pause between records
                        }
                    }

                    // Final status
                    long duration = System.currentTimeMillis() - startTime;
                    publish("Selesai - " + processedRecords + " record dalam " + (duration / 1000) + " detik");

                } catch (Exception e) {
                    System.out.println("Notif : " + e);
                    e.printStackTrace();
                    publish("Error: " + e.getMessage());
                    throw e;
                } finally {
                    // Proper resource cleanup
                    try {
                        if (rs != null) {
                            rs.close();
                        }
                    } catch (SQLException e) {
                        System.out.println("Error closing ResultSet: " + e);
                    }
                    try {
                        if (ps != null) {
                            ps.close();
                        }
                    } catch (SQLException e) {
                        System.out.println("Error closing PreparedStatement: " + e);
                    }
                }

                return htmlContent.toString();
            }

            @Override
            protected void process(List<String> chunks) {
                // Update UI with progress messages (runs on EDT)
                if (!chunks.isEmpty()) {
                    String lastMessage = chunks.get(chunks.size() - 1);
                    updateProgress(lastMessage);
                }
            }

            @Override
            protected void done() {
                isLoadingRadiology = false;
                hideProgress();

                try {
                    if (!isCancelled()) {
                        // Get the final HTML content
                        String finalHtml = get();

                        // Update WebView with final content (runs on EDT)
                        if (finalHtml != null && !finalHtml.isEmpty()) {
                            initializeWebViewOnce(finalHtml);
                        } else {

                            // Show empty state
                            String emptyHtml = "<html><body style='text-align:center; padding:50px;'>"
                                    + "<h3>Tidak ada data radiologi</h3>"
                                    + "<p>Silakan pilih pasien dan periode yang berbeda</p>"
                                    + "</body></html>";
                            initializeWebViewOnce(emptyHtml);
                        }
                    } else {
                        // Cancelled
                        if (lblLoadingStatus != null) {
                            lblLoadingStatus.setText("Dibatalkan");
                            lblLoadingStatus.setVisible(false);
                        }
                    }
                } catch (CancellationException e) {
                    if (lblLoadingStatus != null) {
                        lblLoadingStatus.setText("Dibatalkan");
                        lblLoadingStatus.setVisible(false);
                    }
                } catch (Exception e) {
                    System.out.println("Error in done(): " + e);
                    e.printStackTrace();

                    if (lblLoadingStatus != null) {
                        lblLoadingStatus.setText("Error: " + e.getMessage());
                    }

                    JOptionPane.showMessageDialog(null,
                            "Gagal memuat data radiologi: " + e.getMessage(),
                            "Error",
                            JOptionPane.ERROR_MESSAGE);
                } finally {
                    // Clear worker reference
                    if (currentRadiologyWorker == this) {
                        currentRadiologyWorker = null;
                    }
                }
            }
        };

        // Start the worker
        isLoadingRadiology = true;
        currentRadiologyWorker = worker;
        worker.execute();
    }

    /**
     * Memory-efficient WebView content update
     */
    private void updateWebViewContent(String htmlContent) {
        if (!isWebViewInitialized) {
            initializeWebViewOnce(htmlContent);
        } else {
            // Reuse existing WebView - much more memory efficient
            Platform.runLater(() -> {
                try {
                    if (webViewRiwayatPerawatan != null && webViewRiwayatPerawatan.getEngine() != null) {
                        // Clear previous content first
                        webViewRiwayatPerawatan.getEngine().loadContent("");

                        // Small delay to ensure cleanup, then load new content
                        Timeline timeline = new Timeline(new KeyFrame(Duration.millis(100), e -> {
                            webViewRiwayatPerawatan.getEngine().loadContent(htmlContent);
                        }));
                        timeline.play();
                    }
                } catch (Exception e) {
                    System.err.println("Kesalahan update WebView: " + e.getMessage());
                    fallbackToEditorPane(htmlContent);
                }
            });
        }
    }

    /**
     * Initialize WebView only once to prevent memory leaks
     */
    private void initializeWebViewOnce(String htmlContent) {
        if (PanelGambarWebviewRiwayatPerawatan.getComponentCount() > 0) {
            // If WebView already exists, just update content
            if (webViewRiwayatPerawatan != null) {
                Platform.runLater(() -> {
                    webViewRiwayatPerawatan.getEngine().loadContent(htmlContent);
                });
                return;
            }
            // Clean up existing components first
            PanelGambarWebviewRiwayatPerawatan.removeAll();
        }

        try {
            Platform.runLater(() -> {
                try {
                    // Create WebView only once
                    webViewRiwayatPerawatan = new WebView();
                    // Configure WebView for memory efficiency
                    webViewRiwayatPerawatan.getEngine().setJavaScriptEnabled(true);
                    webViewRiwayatPerawatan.getEngine().getHistory().setMaxSize(0);
                    webViewRiwayatPerawatan.getEngine().setUserStyleSheetLocation(null);

                    // Memory management settings
                    webViewRiwayatPerawatan.getEngine().getLoadWorker().stateProperty().addListener((obs, oldState, newState) -> {
                        if (newState == Worker.State.SUCCEEDED) {
                            System.gc();
                        }
                    });

                    // Load content
                    webViewRiwayatPerawatan.getEngine().loadContent(htmlContent);

                    // Create JFXPanel and Scene only once
                    SwingUtilities.invokeLater(() -> {
                        fxPanel = new JFXPanel();
                        Platform.runLater(() -> {
                            Scene scene = new Scene(webViewRiwayatPerawatan);
                            fxPanel.setScene(scene);
                        });
                        PanelGambarWebviewRiwayatPerawatan.add(fxPanel, BorderLayout.CENTER);
                        PanelGambarWebviewRiwayatPerawatan.revalidate();
                        PanelGambarWebviewRiwayatPerawatan.repaint();
                    });
                } catch (Exception webEx) {
                    System.err.println("Kesalahan inisialisasi WebView: " + webEx.getMessage());
                    SwingUtilities.invokeLater(() -> fallbackToEditorPane(htmlContent));
                }
            });
        } catch (Exception initEx) {
            System.err.println("Kesalahan platform WebView: " + initEx.getMessage());
            fallbackToEditorPane(htmlContent);
        }
    }

    /**
     * Fallback to JEditorPane for memory efficiency
     */
    private void fallbackToEditorPane(String htmlContent) {
        try {
            JEditorPane editorPane = new JEditorPane("text/html", htmlContent);
            editorPane.setEditable(false);

            // Memory optimization for JEditorPane
            editorPane.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);

            JScrollPane scrollPane = new JScrollPane(editorPane);
            scrollPane.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
            scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);

            PanelGambarWebviewRiwayatPerawatan.removeAll();
            PanelGambarWebviewRiwayatPerawatan.add(scrollPane, BorderLayout.CENTER);
            PanelGambarWebviewRiwayatPerawatan.revalidate();
            PanelGambarWebviewRiwayatPerawatan.repaint();

        } catch (Exception e) {
            System.err.println("Kesalahan fallback EditorPane: " + e.getMessage());
        }
    }

