    public StringBuilder tampilgambarRadiologi(String noorder, String tglhasil, String jamhasil, String norawat) {
        htmlgambarradiologi = new StringBuilder();
        String studyId = tampilStudy.getStudyID(noorder);
        if (studyId != null && !studyId.isEmpty()) {
            //Valid.hapusFiledanFolderDalamFolder("dicom_images");
            List<byte[]> images = tampilStudy.getStudyImages(studyId);

            if (!images.isEmpty()) {
                htmlgambarradiologi.append("<tr><td class='header'>Gambar Rontgen (DICOM)</td></tr>");

                // ✅ Get instance IDs separately (only addition needed)
                List<String> instanceIds = tampilStudy.getInstanceIdsForStudy(studyId);

                for (int i = 0; i < images.size(); i++) {
                    byte[] imageData = images.get(i);

                    // ✅ ONLY ADDITION: Apply overlay if we have instance ID
                    if (i < instanceIds.size()) {
                        String instanceId = instanceIds.get(i);
                        imageData = tampilStudy.addPatientOverlay(imageData, instanceId);
                        //System.out.println("Applied patient overlay for instance: " + instanceId);
                    } else {
                        System.out.println("No instance ID available for image " + (i + 1) + ", using original image");
                    }

                    String fileName = "dicom_" + noorder.replaceAll("/", "_") + "_" + (i + 1) + ".jpg";
                    try {
                        // Create directory structure following your project pattern
                        String imageDirectory = "dicom_images/" + studyId;
                        File webImageDir = new File(imageDirectory);
                        webImageDir.mkdirs();

                        File imageFile = new File(webImageDir, fileName);

                        // Convert DICOM to RGB JPEG before saving
                        BufferedImage dicomImage = ImageIO.read(new ByteArrayInputStream(imageData));
                        BufferedImage rgbImage = new BufferedImage(
                                dicomImage.getWidth(),
                                dicomImage.getHeight(),
                                BufferedImage.TYPE_INT_RGB);

                        Graphics2D g = rgbImage.createGraphics();
                        g.drawImage(dicomImage, 0, 0, null);
                        g.dispose();

                        // Save as RGB JPEG
                        ImageIO.write(rgbImage, "jpg", imageFile);

                        // Generate relative web URL (no context path needed)
                        String imageUrl = imageFile.toURI().toURL().toString();

                        // Add image row with web-accessible URL
                        htmlgambarradiologi.append("<tr><td class='content'>")
                                .append("<table width='100%' border='0' cellspacing='0' cellpadding='0' style='margin-bottom:15px;'>")
                                .append("<tr><td align='center' style='padding-bottom:5px; font-weight:bold;'>")
                                .append("DICOM Image ").append(i + 1).append(" of ").append(images.size())
                                .append("</td></tr>")
                                .append("<tr><td align='center'>")
                                .append("<img src='").append(imageUrl).append("' ")
                                .append("width='470' height='auto' ")
                                .append("alt='DICOM Hasil Rontgen ").append(i + 1).append("' ")
                                .append("onerror='this.onerror=null;this.src=\"images/image_not_found.jpg\"' ")
                                .append("style='border:2px solid #007bff; max-width:100%; box-shadow:0 4px 8px rgba(0,0,0,0.1);'/>")
                                .append("</td></tr>")
                                .append("<tr><td align='center' style='padding-top:5px; color:#666; font-size:12px;'>")
                                .append("Source: PACS DICOM Server | ")
                                .append("<a href='").append(imageUrl).append("' target='_blank' style='color:#007bff; text-decoration:none;'>")
                                .append("Open in Browser</a>") // This hyperlink will now work properly
                                .append("</td></tr>");

                        // Add separator between images (except last one)
                        if (i < images.size() - 1) {
                            htmlgambarradiologi.append("<tr><td style='padding:15px 0;'>")
                                    .append("<hr style='margin:0; border:1px solid #ddd;'>")
                                    .append("</td></tr>");
                        }

                        htmlgambarradiologi.append("</table></td></tr>");

                    } catch (Exception e) {
                        System.out.println("Error processing DICOM image: " + e.getMessage());
                        e.printStackTrace(); // Added for better debugging

                        // Optional: Add error image placeholder in HTML
                        htmlgambarradiologi.append("<tr><td class='content'>")
                                .append("<table width='100%' border='0' cellspacing='0' cellpadding='0' style='margin-bottom:15px;'>")
                                .append("<tr><td align='center' style='padding-bottom:5px; font-weight:bold; color:red;'>")
                                .append("Error Loading DICOM Image ").append(i + 1)
                                .append("</td></tr>")
                                .append("<tr><td align='center'>")
                                .append("<img src='images/image_error.jpg' ")
                                .append("width='470' height='auto' alt='Error loading image'/>")
                                .append("</td></tr>")
                                .append("</table></td></tr>");
                    }
                }
            } else {
                htmlgambarradiologi.append("<tr><td class='content'>Tidak ditemukan gambar DICOM hasil</td></tr>");
            }
        } else {
            htmlgambarradiologi.append("<tr><td class='content'>Study ID tidak ditemukan. Ditampilkan gambar hasil unggah manual</td></tr>");
            //ambil gambar dari webserver
            try {
                ps6 = koneksi.prepareStatement("select lokasi_gambar from gambar_radiologi where gambar_radiologi.no_rawat=? order by gambar_radiologi.tgl_periksa,gambar_radiologi.jam");
                try {
                    ps6.setString(1, norawat);
                    rs6 = ps6.executeQuery();
                    List<String> imagePaths = new ArrayList<>();
                    while (rs6.next()) {
                        if (!rs6.getString(1).equals("")) {
                            imagePaths.add(rs6.getString(1));
                        }
                    }

                    if (!imagePaths.isEmpty()) {
                        htmlgambarradiologi.append("<tr><td class='header'>Gambar Rontgen (Hasil Upload Manual)</td></tr>");

                        for (int i = 0; i < imagePaths.size(); i++) {
                            String imageUrl = "http://" + koneksiDB.HOSTHYBRIDWEB() + ":" + koneksiDB.PORTWEB() + "/"
                                    + koneksiDB.HYBRIDWEB() + "/radiologi/" + imagePaths.get(i);

                            htmlgambarradiologi.append("<tr><td class='content'>")
                                    .append("<table width='100%' border='0' cellspacing='0' cellpadding='0' style='margin-bottom:15px;'>")
                                    .append("<tr><td align='center' style='padding-bottom:5px; font-weight:bold;'>")
                                    .append("Manual Upload Image ").append(i + 1).append(" of ").append(imagePaths.size())
                                    .append("</td></tr>")
                                    .append("<tr><td align='center'>")
                                    .append("<img src='").append(imageUrl).append("' ")
                                    .append("width='470' height='auto' ")
                                    .append("alt='Hasil Rontgen Manual Upload ").append(i + 1).append("' ")
                                    .append("onerror='this.onerror=null;this.src=\"image_not_found.jpg\"' ")
                                    .append("style='border:2px solid #007bff; max-width:100%; box-shadow:0 4px 8px rgba(0,0,0,0.1);'/>")
                                    .append("</td></tr>")
                                    .append("<tr><td align='center' style='padding-top:5px; color:#666; font-size:12px;'>")
                                    .append("Source: Manual Upload | ")
                                    .append("<a href='").append(imageUrl).append("' target='_blank' style='color:#007bff; text-decoration:none;'>")
                                    .append("Open in Browser</a>") // Hyperlink added here
                                    .append("</td></tr>");

                            // Add separator between images (except last one)
                            if (i < imagePaths.size() - 1) {
                                htmlgambarradiologi.append("<tr><td style='padding:15px 0;'>")
                                        .append("<hr style='margin:0; border:1px solid #ddd;'>")
                                        .append("</td></tr>");
                            }

                            htmlgambarradiologi.append("</table></td></tr>");
                        }
                    } else {
                        htmlgambarradiologi.append("<tr><td class='content'>Tidak ditemukan gambar hasil</td></tr>");
                    }
                } catch (Exception e) {
                    System.out.println("simrskhanza.DlgCariPeriksaRadiologi.MnLihatHasilActionPerformed() ps6 : " + e);
                } finally {
                    if (rs6 != null) {
                        rs6.close();
                    }
                    if (ps6 != null) {
                        ps6.close();
                    }
                }
            } catch (Exception e) {
                System.out.println("Pesan catch dari ambil gambar upload radiologi " + e);
            }
        }

        return htmlgambarradiologi;
    }

    /**
     * Sets up the WebView component. Call this ONLY ONCE from your form's
     * constructor.
     */
    private void initializeWebView() {
        // Prevent this from ever running more than once
        if (fxPanel != null) {
            return;
        }

        // Ensure Swing components are managed on the Event Dispatch Thread (EDT)
        SwingUtilities.invokeLater(() -> {
            // Create the bridge between Swing and JavaFX
            fxPanel = new JFXPanel();

            // Add the bridge to your Swing panel
            PanelGambarWebviewRiwayatPerawatan.removeAll(); // Clear the panel first
            PanelGambarWebviewRiwayatPerawatan.setLayout(new BorderLayout());
            PanelGambarWebviewRiwayatPerawatan.add(fxPanel, BorderLayout.CENTER);
            PanelGambarWebviewRiwayatPerawatan.revalidate();
            PanelGambarWebviewRiwayatPerawatan.repaint();

            // Create the JavaFX components on the JavaFX Application Thread
            Platform.runLater(() -> {
                webViewRiwayatPerawatan = new WebView();
                Scene scene = new Scene(webViewRiwayatPerawatan);
                fxPanel.setScene(scene); // Set the scene on the panel
            });
        });
    }

    private void menampilkanRiwayatDiagnosaKeperawatan(String norawat) {
        PreparedStatement ps = null;
        ResultSet rs2 = null;

        try {
            if (chkDiagnosaKeperawatan.isSelected()) {

                // ── Helper: proses satu ResultSet dan append ke htmlContent ──────────
                // Kita pakai inner logic dengan method lokal (Java 8+: lambda tidak bisa throws,
                // jadi kita tulis langsung dua blok identik untuk ranap & ralan)
                boolean adaDataApapun = false;
// ════════════════════════════════════════════════════════════════════
                // 1. CEK RALAN
                // ════════════════════════════════════════════════════════════════════
                boolean adaRalan = false;
                ps = koneksi.prepareStatement(
                        "SELECT 1 FROM penilaian_awal_keperawatan_ralan_masalah "
                        + "WHERE no_rawat = ? LIMIT 1");
                ps.setString(1, norawat);
                rs2 = ps.executeQuery();
                if (rs2.next()) {
                    adaRalan = true;
                }
                rs2.close();
                ps.close();

                if (adaRalan) {
                    try {
                        String query
                                = "SELECT\n"
                                + "	master_masalah_keperawatan.kode_masalah,\n"
                                + "	master_masalah_keperawatan.nama_masalah,\n"
                                + "	master_masalah_keperawatan.definisi,\n"
                                + "	penilaian_awal_keperawatan_ralan_masalah.keterangan,\n"
                                + "	COALESCE(penilaian_awal_keperawatan_igd.tanggal, penilaian_awal_keperawatan_ralan.tanggal) AS tanggal_input,\n"
                                + "	penilaian_awal_keperawatan_ralan_masalah.tanggal_eval,\n"
                                + "	penilaian_awal_keperawatan_ralan_masalah.nip,\n"
                                + "	petugas.nama AS nama_petugas,\n"
                                + "	penilaian_awal_keperawatan_ralan_masalah.nipeval,\n"
                                + "	petugas_eval.nama AS nama_petugas_eval\n"
                                + "FROM\n"
                                + "	master_masalah_keperawatan\n"
                                + "	INNER JOIN penilaian_awal_keperawatan_ralan_masalah ON penilaian_awal_keperawatan_ralan_masalah.kode_masalah = master_masalah_keperawatan.kode_masalah\n"
                                + "	LEFT JOIN penilaian_awal_keperawatan_ralan ON penilaian_awal_keperawatan_ralan.no_rawat = penilaian_awal_keperawatan_ralan_masalah.no_rawat\n"
                                + "	LEFT JOIN petugas ON penilaian_awal_keperawatan_ralan_masalah.nip = petugas.nip\n"
                                + "	LEFT JOIN petugas AS petugas_eval ON penilaian_awal_keperawatan_ralan_masalah.nipeval = petugas_eval.nip\n"
                                + "	LEFT JOIN penilaian_awal_keperawatan_igd ON penilaian_awal_keperawatan_ralan_masalah.no_rawat = penilaian_awal_keperawatan_igd.no_rawat  "
                                + "WHERE penilaian_awal_keperawatan_ralan_masalah.no_rawat = ? "
                                + "ORDER BY master_masalah_keperawatan.kode_masalah";

                        ps = koneksi.prepareStatement(query);
                        ps.setString(1, norawat);
                        rs2 = ps.executeQuery();

                        if (rs2.next()) {
                            if (!adaDataApapun) {
                                // Header tabel riwayat — hanya dicetak sekali
                                htmlContent.append(
                                        "<tr class='isi'>"
                                        + "<td valign='top' width='2%'></td>"
                                        + "<td valign='top' width='18%'></td>"
                                        + "<td valign='top' width='1%' align='center'>:</td>"
                                        + "<td valign='top' width='79%'>"
                                        + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                                        + "<tr>"
                                        + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>RIWAYAT DIAGNOSA KEPERAWATAN</td>\n"
                                        + "</tr>"
                                        + "</table>"
                                );
                                adaDataApapun = true;
                            }

                            // Sub-header penanda sumber data
                            htmlContent.append(
                                    "<table width='100%' border='0' align='center' cellpadding='5' cellspacing='0' class='tbl_form' style='margin-top:8px;'>"
                                    + "<tr><td valign='middle' bgcolor='#c8e6c9' align='left' width='100%' "
                                    + "style='font-weight:bold; padding-left:8px;'>IGD atau Rawat Jalan (RALAN)</td></tr>"
                                    + "</table>"
                            );

                            rs2.beforeFirst();
                            int w = 1;

                            while (rs2.next()) {
                                appendBarisDiagnosa(norawat, rs2, w);
                                w++;
                            }
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    } finally {
                        if (rs2 != null) {
                            rs2.close();
                        }
                        if (ps != null) {
                            ps.close();
                        }
                    }
                }
                // ════════════════════════════════════════════════════════════════════
                // 2. CEK RANAP
                // ════════════════════════════════════════════════════════════════════
                boolean adaRanap = false;
                ps = koneksi.prepareStatement(
                        "SELECT 1 FROM penilaian_awal_keperawatan_ranap_masalah "
                        + "WHERE no_rawat = ? LIMIT 1");
                ps.setString(1, norawat);
                rs2 = ps.executeQuery();
                if (rs2.next()) {
                    adaRanap = true;
                }
                rs2.close();
                ps.close();

                if (adaRanap) {
                    try {
                        String query
                                = "SELECT "
                                + "master_masalah_keperawatan.kode_masalah, "
                                + "master_masalah_keperawatan.nama_masalah, "
                                + "master_masalah_keperawatan.definisi, "
                                + "penilaian_awal_keperawatan_ranap_masalah.keterangan, "
                                + "penilaian_awal_keperawatan_ranap.tanggal AS tanggal_input, "
                                + "penilaian_awal_keperawatan_ranap_masalah.tanggal_eval, "
                                + "penilaian_awal_keperawatan_ranap_masalah.nip, "
                                + "petugas.nama AS nama_petugas, "
                                + "penilaian_awal_keperawatan_ranap_masalah.nipeval, "
                                + "petugas_eval.nama AS nama_petugas_eval "
                                + "FROM master_masalah_keperawatan "
                                + "LEFT JOIN penilaian_awal_keperawatan_ranap_masalah "
                                + "ON penilaian_awal_keperawatan_ranap_masalah.kode_masalah = master_masalah_keperawatan.kode_masalah "
                                + "LEFT JOIN penilaian_awal_keperawatan_ranap "
                                + "ON penilaian_awal_keperawatan_ranap.no_rawat = penilaian_awal_keperawatan_ranap_masalah.no_rawat "
                                + "LEFT JOIN petugas "
                                + "ON penilaian_awal_keperawatan_ranap_masalah.nip = petugas.nip "
                                + "LEFT JOIN petugas AS petugas_eval "
                                + "ON penilaian_awal_keperawatan_ranap_masalah.nipeval = petugas_eval.nip "
                                + "WHERE penilaian_awal_keperawatan_ranap_masalah.no_rawat = ? "
                                + "ORDER BY master_masalah_keperawatan.kode_masalah";

                        ps = koneksi.prepareStatement(query);
                        ps.setString(1, norawat);
                        rs2 = ps.executeQuery();

                        if (rs2.next()) {
                            if (!adaDataApapun) {
                                // Header tabel riwayat — hanya dicetak sekali
                                htmlContent.append(
                                        "<tr class='isi'>"
                                        + "<td valign='top' width='2%'></td>"
                                        + "<td valign='top' width='18%'></td>"
                                        + "<td valign='top' width='1%' align='center'>:</td>"
                                        + "<td valign='top' width='79%'>"
                                        + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                                        + "<tr>"
                                        + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>RIWAYAT DIAGNOSA KEPERAWATAN</td>\n"
                                        + "</tr>"
                                        + "</table>"
                                );
                                adaDataApapun = true;
                            }

                            // Sub-header penanda sumber data
                            htmlContent.append(
                                    "<table width='100%' border='0' align='center' cellpadding='5' cellspacing='0' class='tbl_form' style='margin-top:8px;'>"
                                    + "<tr><td valign='middle' bgcolor='#b0c4de' align='left' width='100%' "
                                    + "style='font-weight:bold; padding-left:8px;'>Rawat Inap (RANAP)</td></tr>"
                                    + "</table>"
                            );

                            rs2.beforeFirst();
                            int w = 1;

                            while (rs2.next()) {
                                appendBarisDiagnosa(norawat, rs2, w);
                                w++;
                            }
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    } finally {
                        if (rs2 != null) {
                            rs2.close();
                        }
                        if (ps != null) {
                            ps.close();
                        }
                    }
                }

                // Tutup wrapper <td> yang dibuka di header (hanya jika ada data)
                if (adaDataApapun) {
                    htmlContent.append("</td></tr>");
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void appendBarisDiagnosa(String norawat, ResultSet rs2, int w) throws Exception {
        String kodeMasalah = rs2.getString("kode_masalah");
        String Masalah = rs2.getString("nama_masalah");
        String definisi = rs2.getString("definisi") != null ? rs2.getString("definisi") : "";
        String keterangan = rs2.getString("keterangan") != null ? rs2.getString("keterangan") : "";
        String tanggalInput = rs2.getString("tanggal_input") != null ? rs2.getString("tanggal_input") : "";
        String tanggalEval = rs2.getString("tanggal_eval") != null ? rs2.getString("tanggal_eval") : "";
        String nipInput = rs2.getString("nip") != null ? rs2.getString("nip") : "";
        String namaPetugasInput = rs2.getString("nama_petugas") != null ? rs2.getString("nama_petugas") : "";
        String nipEval = rs2.getString("nipeval") != null ? rs2.getString("nipeval") : "";
        String namaPetugasEval = rs2.getString("nama_petugas_eval") != null ? rs2.getString("nama_petugas_eval") : "";
        String kodeDiagnosa = kodeMasalah;

        // SDKI
        java.util.List<String> sdkiList = new java.util.ArrayList<>();
        PreparedStatement psSDKI = null;
        ResultSet rsSDKI = null;
        try {
            psSDKI = koneksi.prepareStatement(
                    "SELECT item FROM data_detail_diagnosa_kep "
                    + "WHERE no_rawat = ? AND kode_masalah = ? "
                    + "ORDER BY kode_diagkep");
            psSDKI.setString(1, norawat);
            psSDKI.setString(2, kodeMasalah);
            rsSDKI = psSDKI.executeQuery();
            while (rsSDKI.next()) {
                String item = rsSDKI.getString("item");
                if (item != null && !item.trim().isEmpty()) {
                    sdkiList.add(item);
                }
            }
        } catch (Exception e) {
            System.out.println("Error load SDKI: " + e);
        } finally {
            if (rsSDKI != null) {
                rsSDKI.close();
            }
            if (psSDKI != null) {
                psSDKI.close();
            }
        }

        // SLKI
        java.util.List<String> slkiList = new java.util.ArrayList<>();
        PreparedStatement psSLKI = null;
        ResultSet rsSLKI = null;
        try {
            psSLKI = koneksi.prepareStatement(
                    "SELECT kode_slki FROM data_detail_slki "
                    + "WHERE no_rawat = ? AND kode_masalah = ?");
            psSLKI.setString(1, norawat);
            psSLKI.setString(2, kodeMasalah);
            rsSLKI = psSLKI.executeQuery();
            while (rsSLKI.next()) {
                String kodeSlki = rsSLKI.getString("kode_slki");
                PreparedStatement psItem = null;
                ResultSet rsItem = null;
                try {
                    psItem = koneksi.prepareStatement(
                            "SELECT item FROM master_diagnosa_keperawatan "
                            + "WHERE kode_masalah = ? AND kode_rencana = ? AND kategori = 'SLKI'");
                    psItem.setString(1, kodeMasalah);
                    psItem.setString(2, kodeSlki);
                    rsItem = psItem.executeQuery();
                    if (rsItem.next()) {
                        slkiList.add(rsItem.getString("item"));
                    }
                } finally {
                    if (rsItem != null) {
                        rsItem.close();
                    }
                    if (psItem != null) {
                        psItem.close();
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Error load SLKI: " + e);
        } finally {
            if (rsSLKI != null) {
                rsSLKI.close();
            }
            if (psSLKI != null) {
                psSLKI.close();
            }
        }

        // SIKI
        java.util.List<String> sikiList = new java.util.ArrayList<>();
        PreparedStatement psSIKI = null;
        ResultSet rsSIKI = null;
        try {
            psSIKI = koneksi.prepareStatement(
                    "SELECT kode_siki FROM data_detail_siki "
                    + "WHERE no_rawat = ? AND kode_masalah = ?");
            psSIKI.setString(1, norawat);
            psSIKI.setString(2, kodeMasalah);
            rsSIKI = psSIKI.executeQuery();
            while (rsSIKI.next()) {
                String kodeSiki = rsSIKI.getString("kode_siki");
                PreparedStatement psItem = null;
                ResultSet rsItem = null;
                try {
                    psItem = koneksi.prepareStatement(
                            "SELECT item FROM master_diagnosa_keperawatan "
                            + "WHERE kode_masalah = ? AND kode_rencana = ? AND kategori = 'SIKI'");
                    psItem.setString(1, kodeMasalah);
                    psItem.setString(2, kodeSiki);
                    rsItem = psItem.executeQuery();
                    if (rsItem.next()) {
                        sikiList.add(rsItem.getString("item"));
                    }
                } finally {
                    if (rsItem != null) {
                        rsItem.close();
                    }
                    if (psItem != null) {
                        psItem.close();
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Error load SIKI: " + e);
        } finally {
            if (rsSIKI != null) {
                rsSIKI.close();
            }
            if (psSIKI != null) {
                psSIKI.close();
            }
        }

        int maxRows = Math.max(Math.max(sdkiList.size(), slkiList.size()), sikiList.size());
        if (maxRows == 0) {
            maxRows = 1;
        }

        htmlContent.append(
                "<table width='100%' border='0' align='center' cellpadding='5' cellspacing='0' class='tbl_form' style='margin-top:10px;'>"
                + "<tr>"
                + "<td valign='top' width='20%' style='font-weight:bold;'>Petugas Input</td>"
                + "<td valign='top' width='30%'>" + nipInput + " - " + namaPetugasInput + "</td>"
                + "<td valign='top' width='20%' style='font-weight:bold;'>Tanggal Input</td>"
                + "<td valign='top' width='30%'>" + tanggalInput + "</td>"
                + "</tr>"
                + "</table>"
        );

        htmlContent.append(
                "<table width='100%' border='1' align='center' cellpadding='5' cellspacing='0' class='tbl_form' style='border-collapse:collapse;'>"
                + "<tr align='center' bgcolor='#FFFAF8'>"
                + "<td valign='middle' width='3%'  style='font-weight:bold;'>No</td>"
                + "<td valign='middle' width='12%' style='font-weight:bold;'>Masalah Keperawatan</td>"
                + "<td valign='middle' width='15%' style='font-weight:bold;'>Definisi</td>"
                + "<td valign='middle' width='17%' style='font-weight:bold;'>SDKI</td>"
                + "<td valign='middle' width='17%' style='font-weight:bold;'>SLKI</td>"
                + "<td valign='middle' width='17%' style='font-weight:bold;'>SIKI</td>"
                + "<td valign='middle' width='8%'  style='font-weight:bold;'>Keterangan</td>"
                + "<td valign='middle' width='8%'  style='font-weight:bold;'>Tanggal Evaluasi</td>"
                + "<td valign='middle' width='8%'  style='font-weight:bold;'>Petugas Eval</td>"
                + "</tr>"
        );

        for (int i = 0; i < maxRows; i++) {
            htmlContent.append("<tr>");

            if (i == 0) {
                htmlContent.append(
                        "<td valign='top' align='center' rowspan='" + maxRows + "'>" + w + "</td>"
                        + "<td valign='top' align='left'   rowspan='" + maxRows + "'>" + kodeDiagnosa + " - " + Masalah + "</td>"
                        + "<td valign='top' align='justify' rowspan='" + maxRows + "'>" + definisi + "</td>"
                );
            }

            htmlContent.append(i < sdkiList.size()
                    ? "<td valign='top' align='left'>" + (i + 1) + ". " + sdkiList.get(i) + "</td>"
                    : "<td valign='top' align='left'></td>");

            htmlContent.append(i < slkiList.size()
                    ? "<td valign='top' align='left'>" + (i + 1) + ". " + slkiList.get(i) + "</td>"
                    : "<td valign='top' align='left'></td>");

            htmlContent.append(i < sikiList.size()
                    ? "<td valign='top' align='left'>" + (i + 1) + ". " + sikiList.get(i) + "</td>"
                    : "<td valign='top' align='left'></td>");

            if (i == 0) {
                String petugasEvalText = (!nipEval.isEmpty() && !namaPetugasEval.isEmpty())
                        ? nipEval + " - " + namaPetugasEval : "";
                htmlContent.append(
                        "<td valign='top' align='left' rowspan='" + maxRows + "'>" + keterangan + "</td>"
                        + "<td valign='top' align='left' rowspan='" + maxRows + "'>" + tanggalEval + "</td>"
                        + "<td valign='top' align='left' rowspan='" + maxRows + "'>" + petugasEvalText + "</td>"
                );
            }

            htmlContent.append("</tr>");
        }

        htmlContent.append("</table>");
    }

