                    html.append("</td></tr>");
                    html.append("<tr><td align='center'>");
                    html.append("<table width='470' border='1' cellspacing='0' cellpadding='20' style='border:2px solid #dc3545; background-color:#f8d7da; margin:0 auto;'>");
