    /**
     * Helper 3: Process PDFs efficiently
     *
     * @param resultSet ResultSet with PDF data
     * @param norawat Patient registration number
     * @param dpi Image quality (96 recommended)
     * @return List of processed PDF data
     */
    private List<PdfDocumentData> processPdfDocuments(ResultSet resultSet, String norawat, float dpi) throws SQLException {
        List<PdfDocumentData> pdfDocuments = new ArrayList<>();

        while (resultSet.next()) {
            PdfDocumentData docData = new PdfDocumentData();
            docData.fileName = resultSet.getString("nama");
            docData.fileLocation = resultSet.getString("lokasi_file");
            docData.pdfUrl = "http://" + koneksiDB.HOSTHYBRIDWEB() + ":" + koneksiDB.PORTWEB()
                    + "/" + koneksiDB.HYBRIDWEB() + "/berkasrawat/" + docData.fileLocation;

            System.out.println("========================================");
            System.out.println("Processing: " + docData.fileName);
            //System.out.println("URL: " + docData.pdfUrl);

            String baseFileName = docData.fileLocation.replaceAll(".*/", "");
            docData.imagePaths = convertPdfToImageCache(docData.pdfUrl, norawat, baseFileName, dpi);

            //System.out.println("Result: " + docData.imagePaths.size() + " images generated");
            System.out.println("========================================");

            pdfDocuments.add(docData);
        }

        return pdfDocuments;
    }

    /**
     * Inner class to hold PDF document data
     */
    private static class PdfDocumentData {

        String fileName;
        String fileLocation;
        String pdfUrl;
        List<String> imagePaths; // Changed from imageUrls to imagePaths
    }

    /**
     * Converts base64 image data to JPEG format
     *
     * @param base64Data The base64 string (with or without data URI prefix)
     * @return Base64 encoded JPEG image with data URI prefix, or null if
     * conversion fails
     */
    private String convertToJpegBase64(String base64Data) {
        if (base64Data == null || base64Data.isEmpty()) {
            return null;
        }

        try {
            // Remove data URI prefix if exists
            String base64String = base64Data;
            if (base64Data.contains(",")) {
                base64String = base64Data.split(",")[1];
            }

            // Decode base64 to bytes
            byte[] imageBytes = javax.xml.bind.DatatypeConverter.parseBase64Binary(base64String);

            // Convert to BufferedImage
            ByteArrayInputStream bais = new ByteArrayInputStream(imageBytes);
            BufferedImage image = javax.imageio.ImageIO.read(bais);
            bais.close();

            if (image == null) {
                return null;
            }

            // Create new image with white background (JPEG doesn't support transparency)
            BufferedImage jpegImage = new BufferedImage(
                    image.getWidth(),
                    image.getHeight(),
                    BufferedImage.TYPE_INT_RGB
            );

            Graphics2D g = jpegImage.createGraphics();
            g.setColor(Color.WHITE);
            g.fillRect(0, 0, jpegImage.getWidth(), jpegImage.getHeight());
            g.drawImage(image, 0, 0, null);
            g.dispose();

            // Convert to JPEG bytes
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            javax.imageio.ImageIO.write(jpegImage, "jpg", baos);
            baos.flush();
            byte[] jpegBytes = baos.toByteArray();
            baos.close();

            // Encode to base64
            String jpegBase64 = javax.xml.bind.DatatypeConverter.printBase64Binary(jpegBytes);

            return "data:image/jpeg;base64," + jpegBase64;

        } catch (Exception e) {
            System.out.println("Error converting image: " + e);
            return null;
        }
    }

