    private String toRomawi(String val) {
        if (val == null || val.trim().isEmpty()) {
            return "";
        }
        switch (val.trim()) {
            case "1":
                return "I";
            case "2":
                return "II";
            case "3":
                return "III";
            case "4":
                return "IV";
            case "5":
                return "V";
            case "6":
                return "VI";
            default:
                return val.trim().toUpperCase();
        }
    }

    private void menampilkanPengawasanRR(String norawat) {
        try {
            if (chkLaporanAnestesi.isSelected() == true) {
                try {
                    rs2 = koneksi.prepareStatement(
                            "SELECT p.no_rawat, p.tanggal_input, p.jam_masuk, p.jam_pulang, "
                            + "  p.kembali_ke_ruang, p.jam_kembali, "
                            + "  p.kd_dokter_operator, p.kd_dokter_anestesi, p.nip_perawat, "
                            + "  d1.nm_dokter AS nm_bedah, "
                            + "  d2.nm_dokter AS nm_anestesi, "
                            + "  pt.nama AS nm_perawat, "
                            + "  t.waktu, t.td_sistolik, t.td_diastolik, t.nadi, "
                            + "  t.rr, t.sao2, t.suhu, t.bb, t.skor_nyeri, t.sesi "
                            + "FROM pengawasan_ruang_recovery p "
                            + "LEFT JOIN pemantauan_recovery_ttv t ON t.no_rawat = p.no_rawat "
                            + "LEFT JOIN dokter  d1 ON p.kd_dokter_operator = d1.kd_dokter "
                            + "LEFT JOIN dokter  d2 ON p.kd_dokter_anestesi = d2.kd_dokter "
                            + "LEFT JOIN petugas pt ON p.nip_perawat = pt.nip "
                            + "WHERE p.no_rawat = '" + norawat + "' "
                            + "ORDER BY t.sesi ASC, t.waktu ASC"
                    ).executeQuery();

                    if (rs2.next()) {
                        // ── Ambil data header dari baris pertama ──────────────
                        String tglInput = rs2.getString("tanggal_input") != null ? rs2.getString("tanggal_input") : "-";
                        String jamMasuk = rs2.getString("jam_masuk") != null ? rs2.getString("jam_masuk") : "-";
                        String jamPulang = rs2.getString("jam_pulang") != null ? rs2.getString("jam_pulang") : "-";
                        String kembaliRuang = rs2.getString("kembali_ke_ruang") != null ? rs2.getString("kembali_ke_ruang") : "-";
                        String jamKembali = rs2.getString("jam_kembali") != null ? rs2.getString("jam_kembali") : "-";
                        String kdBedah = rs2.getString("kd_dokter_operator") != null ? rs2.getString("kd_dokter_operator") : "";
                        String nmBedah = rs2.getString("nm_bedah") != null ? rs2.getString("nm_bedah") : "-";
                        String kdAnestesi = rs2.getString("kd_dokter_anestesi") != null ? rs2.getString("kd_dokter_anestesi") : "";
                        String nmAnestesi = rs2.getString("nm_anestesi") != null ? rs2.getString("nm_anestesi") : "-";
                        String nipPerawat = rs2.getString("nip_perawat") != null ? rs2.getString("nip_perawat") : "";
                        String nmPerawat = rs2.getString("nm_perawat") != null ? rs2.getString("nm_perawat") : "-";

                        htmlContent.append(
                                "<tr class='isi'>"
                                + "<td valign='top' width='2%'></td>"
                                + "<td valign='top' width='18%'></td>"
                                + "<td valign='top' width='1%' align='center'>:</td>"
                                + "<td valign='top' width='79%'>"
                                // Judul
                                + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>Pengawasan Ruang Recovery</td>"
                                + "</tr>"
                                + "</table>"
                                // Header petugas & jam
                                + "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td width='33%' border='0'>Dokter Operator : " + kdBedah + " " + nmBedah + "</td>"
                                + "<td width='33%' border='0'>Dokter Anestesi : " + kdAnestesi + " " + nmAnestesi + "</td>"
                                + "<td width='34%' border='0'>Perawat : " + nipPerawat + " " + nmPerawat + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td width='33%' border='0'>Tanggal : " + tglInput + "</td>"
                                + "<td width='33%' border='0'>Jam Masuk Recovery : " + jamMasuk + "</td>"
                                + "<td width='34%' border='0'>Jam Pulang Recovery : " + jamPulang + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td width='33%' border='0'>Kembali Ke Ruang : " + kembaliRuang + "</td>"
                                + "<td width='33%' border='0'>Jam Kembali : " + jamKembali + "</td>"
                                + "<td width='34%' border='0'></td>"
                                + "</tr>"
                                + "</table>"
                                // Header tabel TTV
                                + "<table width='100%' border='1' align='center' cellpadding='3px' cellspacing='0' class='tbl_form' style='border-collapse:collapse;margin-top:6px;'>"
                                + "<tr style='background-color:#577d7f;color:white;font-weight:bold;text-align:center;'>"
                                + "<td>No</td><td>Waktu</td><td>TD (mmHg)</td>"
                                + "<td>Nadi</td><td>RR</td><td>SPO2</td>"
                                + "<td>Suhu (&deg;C)</td><td>BB (kg)</td><td>Skor Nyeri</td><td>Sesi</td>"
                                + "</tr>"
                        );

                        // ── Loop baris TTV ─────────────────────────────────────
                        rs2.beforeFirst();
                        int no = 1;
                        while (rs2.next()) {
                            String tdGabung = rs2.getString("td_sistolik") + "/" + rs2.getString("td_diastolik");
                            String bgColor = (no % 2 == 0) ? "#f5f5f5" : "#ffffff";
                            htmlContent.append(
                                    "<tr style='background-color:" + bgColor + ";text-align:center;'>"
                                    + "<td>" + no++ + "</td>"
                                    + "<td>" + rs2.getString("waktu") + "</td>"
                                    + "<td>" + tdGabung + "</td>"
                                    + "<td>" + rs2.getString("nadi") + "</td>"
                                    + "<td>" + rs2.getString("rr") + "</td>"
                                    + "<td>" + rs2.getString("sao2") + "</td>"
                                    + "<td>" + rs2.getString("suhu") + "</td>"
                                    + "<td>" + rs2.getString("bb") + "</td>"
                                    + "<td>" + rs2.getString("skor_nyeri") + "</td>"
                                    + "<td>Sesi " + rs2.getInt("sesi") + "</td>"
                                    + "</tr>"
                            );
                        }

                        htmlContent.append(
                                "</table>"
                                + "</td>"
                                + "</tr>"
                        );
                    }
                } catch (Exception e) {
                    System.out.println("Notifikasi : " + e);
                } finally {
                    if (rs2 != null) {
                        rs2.close();
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Notif Pengawasan RR : " + e);
        }
    }

    private void menampilkanGrafikTTV(String norawat) {
        try {
            // --- Kondisi checkbox (asumsi ada chkGrafikTTV) ---
            if (chkSkorAldrettePascaAnestesi.isSelected() == true) {
                java.sql.PreparedStatement ps2 = null;
                java.sql.ResultSet rs2 = null;
                // 1. CEK APAKAH ADA DATA TTV UNTUK NORAWAT INI
                boolean adaData = false;
                java.sql.PreparedStatement psCek = null;
                java.sql.ResultSet rsCek = null;
                try {
                    String sqlCek = "SELECT COUNT(*) FROM pemantauan_recovery_ttv WHERE no_rawat = ?";
                    psCek = koneksi.prepareStatement(sqlCek);
                    psCek.setString(1, norawat);
                    rsCek = psCek.executeQuery();
                    if (rsCek.next() && rsCek.getInt(1) > 0) {
                        adaData = true;
                    }
                } catch (Exception e) {
                    System.out.println("Gagal cek data TTV: " + e);
                } finally {
                    try {
                        if (rsCek != null) {
                            rsCek.close();
                        }
                    } catch (Exception e) {
                    }
                    try {
                        if (psCek != null) {
                            psCek.close();
                        }
                    } catch (Exception e) {
                    }
                }

                if (!adaData) {
                    return;
                }
                try {
                    // 1. GRAFIK TTV (Dari DlgPengawasanRuangRecovery) - instance lokal
                    DlgPengawasanRuangRecovery dlgGrafik = new DlgPengawasanRuangRecovery(null, false);
                    String base64 = dlgGrafik.getGrafikBase64(norawat, 700, 300);

                    if (base64 != null && !base64.isEmpty()) {
                        try {
                            byte[] imageBytes = java.util.Base64.getDecoder().decode(base64);
                            java.io.File tempFile = java.io.File.createTempFile("grafik_ttv_" + norawat.replaceAll("/", ""), ".png");
                            tempFile.deleteOnExit();
                            java.nio.file.Files.write(tempFile.toPath(), imageBytes);
                            String pathGambar = tempFile.getAbsolutePath().replace("\\", "/");

                            htmlContent.append(
                                    "<tr class='isi'>"
                                    + "<td valign='top' width='2%'></td>"
                                    + "<td valign='top' width='18%'></td>"
                                    + "<td valign='top' width='1%' align='center'>:</td>"
                                    + "<td valign='top' width='79%'>"
                                    + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                                    + "<tr>"
                                    + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>Grafik Pemantauan Status Fisiologis</td>\n"
                                    + "</tr>"
                                    + "</table>"
                                    + "</td></tr>"
                            );

                            htmlContent.append("<tr class='isi'>")
                                    .append("<td valign='top' colspan='4'>")
                                    .append("<table width='100%'><tr><td align='center'>")
                                    .append("<img src='file:///").append(pathGambar).append("' width='700' height='300'/>")
                                    .append("</td></tr></table>")
                                    .append("</td></tr>");

                        } catch (Exception ex) {
                            System.out.println("Gagal konversi Base64 Grafik: " + ex);
                        }
                    }

                    // 2. TABEL TTV (Dari pemantauan_recovery_ttv)
                    try {
                        String sql = "SELECT t.id, t.no_rawat, t.waktu, "
                                + "t.td_sistolik, t.td_diastolik, t.nadi, "
                                + "t.rr, t.sao2, t.suhu, t.bb, t.skor_nyeri, t.sesi, "
                                + "t.kd_dokter_operator, t.kd_dokter_anestesi, t.nip_perawat, "
                                + "t.tanggal_input, "
                                + "p.jam_masuk, p.jam_pulang, p.kembali_ke_ruang, p.jam_kembali "
                                + "FROM pemantauan_recovery_ttv t "
                                + "LEFT JOIN pengawasan_ruang_recovery p ON p.no_rawat = t.no_rawat "
                                + "WHERE t.no_rawat = ? "
                                + "ORDER BY t.sesi ASC, t.waktu ASC";

                        ps2 = koneksi.prepareStatement(sql);
                        ps2.setString(1, norawat);
                        rs2 = ps2.executeQuery();

                        if (rs2.next()) {
                            htmlContent.append(
                                    "<tr class='isi'>"
                                    + "<td valign='top' width='2%'></td>"
                                    + "<td valign='top' width='18%'></td>"
                                    + "<td valign='top' width='1%' align='center'>:</td>"
                                    + "<td valign='top' width='79%'>"
                                    + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                                    + "<tr>"
                                    + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>Pemantauan Tanda-Tanda Vital (TTV) Recovery Room</td>\n"
                                    + "</tr>"
                                    + "</table>"
                                    + "<table width='100%' border='0' align='center' cellpadding='3px' cellspacing='0' class='tbl_form'>"
                                    + "<tr align='center'>"
                                    + "<td valign='top' width='4%' bgcolor='#FFFAF8'>No.</td>"
                                    + "<td valign='top' width='14%' bgcolor='#FFFAF8'>Waktu & Sesi</td>"
                                    + "<td valign='top' width='14%' bgcolor='#FFFAF8'>TD (S/D)</td>"
                                    + "<td valign='top' width='10%' bgcolor='#FFFAF8'>Nadi</td>"
                                    + "<td valign='top' width='10%' bgcolor='#FFFAF8'>RR</td>"
                                    + "<td valign='top' width='10%' bgcolor='#FFFAF8'>SaO2</td>"
                                    + "<td valign='top' width='10%' bgcolor='#FFFAF8'>Suhu</td>"
                                    + "<td valign='top' width='10%' bgcolor='#FFFAF8'>Nyeri</td>"
                                    + "<td valign='top' width='18%' bgcolor='#FFFAF8'>Petugas</td>"
                                    + "</tr>"
                            );

                            rs2.beforeFirst();
                            int no = 1;

                            while (rs2.next()) {
                                String td = rs2.getString("td_sistolik") + "/" + rs2.getString("td_diastolik");
                                String waktuSesi = rs2.getString("waktu") + "<br><b>Sesi " + rs2.getInt("sesi") + "</b>";

                                htmlContent.append(
                                        "<tr>"
                                        + "<td valign='top' align='center'>" + no + "</td>"
                                        + "<td valign='top' align='center'>" + waktuSesi + "</td>"
                                        + "<td valign='top' align='center'>" + td + " mmHg</td>"
                                        + "<td valign='top' align='center'>" + rs2.getString("nadi") + " x/m</td>"
                                        + "<td valign='top' align='center'>" + rs2.getString("rr") + " x/m</td>"
                                        + "<td valign='top' align='center'>" + rs2.getString("sao2") + " %</td>"
                                        + "<td valign='top' align='center'>" + rs2.getString("suhu") + " &deg;C</td>"
                                        + "<td valign='top' align='center'>" + rs2.getString("skor_nyeri") + "</td>"
                                        + "<td valign='top' align='center'>" + rs2.getString("nip_perawat") + "</td>"
                                        + "</tr>"
                                );
                                no++;
                            }

                            htmlContent.append(
                                    "</table>"
                                    + "</td>"
                                    + "</tr>"
                            );
                        }
                    } catch (Exception e) {
                        System.out.println("Gagal memuat Tabel pemantauan_recovery_ttv: " + e);
                    } finally {
                        try {
                            if (rs2 != null) {
                                rs2.close();
                            }
                            if (ps2 != null) {
                                ps2.close();
                            }
                        } catch (Exception e) {
                            System.out.println("Error Closing RS TTV: " + e);
                        }
                    }

                } catch (Exception e) {
                    System.out.println("Notifikasi Grafik TTV: " + e);
                }
            }

        } catch (Exception e) {
            System.out.println("Notif menampilkan Grafik TTV: " + e);
        }
    }

