    private void menampilkanObservasiProOperasi(String norawat) {
        try {
            rs2 = koneksi.prepareStatement(
                    "SELECT\n"
                    + "  reg_periksa.no_rawat,\n"
                    + "  pasien.no_rkm_medis,\n"
                    + "  pasien.nm_pasien,\n"
                    + "  pasien.jk,\n"
                    + "  pasien.tgl_lahir,\n"
                    + "  observasi_pro_operasi.tgl_perawatan,\n"
                    + "  observasi_pro_operasi.jam_rawat,\n"
                    + "  observasi_pro_operasi.td,\n"
                    + "  observasi_pro_operasi.nadi,\n"
                    + "  observasi_pro_operasi.rr,\n"
                    + "  observasi_pro_operasi.suhu,\n"
                    + "  observasi_pro_operasi.nip,\n"
                    + "  petugas.nama AS nama_petugas,\n"
                    + "  observasi_pro_operasi.Checklist_Subjek,\n"
                    + "  observasi_pro_operasi.Checklist_Planning,\n"
                    + "  observasi_pro_operasi.ku,\n"
                    + "  observasi_pro_operasi.kesadaran,\n"
                    + "  observasi_pro_operasi.his,\n"
                    + "  observasi_pro_operasi.keterangan_his,\n"
                    + "  observasi_pro_operasi.kekuatan_his,\n"
                    + "  observasi_pro_operasi.denyut_jantung,\n"
                    + "  observasi_pro_operasi.keterangan_denyut_jantung,\n"
                    + "  observasi_pro_operasi.teratur,\n"
                    + "  observasi_pro_operasi.bandle_ring,\n"
                    + "  observasi_pro_operasi.penurunan_bag,\n"
                    + "  observasi_pro_operasi.inpartu_kala2,\n"
                    + "  observasi_pro_operasi.vagina_toucher,\n"
                    + "  observasi_pro_operasi.gravida,\n"
                    + "  observasi_pro_operasi.partus,\n"
                    + "  observasi_pro_operasi.aborsi,\n"
                    + "  observasi_pro_operasi.pro_sc\n"
                    + "FROM\n"
                    + "  reg_periksa\n"
                    + "  INNER JOIN pasien ON reg_periksa.no_rkm_medis = pasien.no_rkm_medis\n"
                    + "  INNER JOIN observasi_pro_operasi ON reg_periksa.no_rawat = observasi_pro_operasi.no_rawat\n"
                    + "  LEFT JOIN petugas ON observasi_pro_operasi.nip = petugas.nip\n"
                    + "WHERE observasi_pro_operasi.no_rawat='" + norawat + "'\n"
                    + "ORDER BY observasi_pro_operasi.tgl_perawatan, observasi_pro_operasi.jam_rawat").executeQuery();

            if (rs2.next()) {
                htmlContent.append(
                        "<tr class='isi'>"
                        + "<td valign='top' width='2%'></td>"
                        + "<td valign='top' width='18%'></td>"
                        + "<td valign='top' width='1%' align='center'>:</td>"
                        + "<td valign='top' width='79%'>"
                        + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>\n"
                        + "<tr>"
                        + "<td valign='middle' bgcolor='#577d7f' align='center' width='100%' style='font-weight: bold; color: white;'>"
                        + "<b>STANDAR ASUHAN KEBIDANAN PRO OPERASI SC</b> (diisi oleh bidan/perawat)</td>\n"
                        + "</tr>"
                        + "</table>"
                        + "<table width='100%' border='1' align='center' cellpadding='5' cellspacing='0' class='tbl_form'>"
                        + "<tr bgcolor='#a7fac3'>"
                        + "<td width='10%' align='center'><b>Tgl / Jam</b></td>"
                        + "<td width='22%' align='center'><b>Subyek</b></td>"
                        + "<td width='30%' align='center'><b>Obyek</b></td>"
                        + "<td width='20%' align='center'><b>Assesment</b></td>"
                        + "<td width='18%' align='center'><b>Planning</b></td>"
                        + "</tr>"
                );

                rs2.beforeFirst();
                while (rs2.next()) {

                    // --- SUBYEK: checklist dipisah koma jadi bullet list ---
                    String subyekRaw = rs2.getString("Checklist_Subjek");
                    StringBuilder subyekList = new StringBuilder();
                    if (subyekRaw != null && !subyekRaw.trim().isEmpty()) {
                        for (String item : subyekRaw.split(",")) {
                            if (!item.trim().isEmpty()) {
                                subyekList.append("<li>").append(item.trim()).append("</li>");
                            }
                        }
                    }

                    // --- PLANNING: checklist dipisah koma jadi bullet list ---
                    String planningRaw = rs2.getString("Checklist_Planning");
                    StringBuilder planningList = new StringBuilder();
                    if (planningRaw != null && !planningRaw.trim().isEmpty()) {
                        for (String item : planningRaw.split(",")) {
                            if (!item.trim().isEmpty()) {
                                planningList.append("<li>").append(item.trim()).append("</li>");
                            }
                        }
                    }

                    htmlContent.append(
                            "<tr class='isi'>"
                            // Kolom Tgl/Jam
                            + "<td valign='top' align='center'>"
                            + rs2.getString("tgl_perawatan") + "<br/>" + rs2.getString("jam_rawat")
                            + "</td>"
                            // Kolom SUBYEK
                            + "<td valign='top'>"
                            + "<ul style='margin-top:2px; padding-left:15px; list-style-type: disc;'>"
                            + (subyekList.length() == 0 ? "-" : subyekList.toString())
                            + "</ul>"
                            + "</td>"
                            // Kolom OBYEK
                            + "<td valign='top'>"
                            + "1. KU : " + nullToStrip(rs2.getString("ku")) + "<br/>"
                            + "2. Kesadaran : " + nullToStrip(rs2.getString("kesadaran")) + "<br/>"
                            + "3. Tanda Vital : TD " + nullToStrip(rs2.getString("td")) + " mmHg"
                            + ", Suhu " + nullToStrip(rs2.getString("suhu")) + "&deg;C"
                            + ", Nadi " + nullToStrip(rs2.getString("nadi")) + " x/mnt"
                            + ", RR " + nullToStrip(rs2.getString("rr")) + " x/mnt<br/>"
                            + "4. His : " + nullToStrip(rs2.getString("his"))
                            + " (" + nullToStrip(rs2.getString("keterangan_his")) + ")"
                            + ", Kekuatan : " + nullToStrip(rs2.getString("kekuatan_his")) + "<br/>"
                            + "5. DJJ : " + nullToStrip(rs2.getString("denyut_jantung")) + " " + nullToStrip(rs2.getString("keterangan_denyut_jantung")) + " x/mnt, "
                            + nullToStrip(rs2.getString("teratur")) + "<br/>"
                            + "6. Penurunan bag. bawah janin : " + nullToStrip(rs2.getString("penurunan_bag")) + "<br/>"
                            + "7. Bandle Ring : " + nullToStrip(rs2.getString("bandle_ring")) + "<br/>"
                            + "8. Tanda inpartu kala II : " + nullToStrip(rs2.getString("inpartu_kala2")) + "<br/>"
                            + "9. Vagina Toucher : " + nullToStrip(rs2.getString("vagina_toucher"))
                            + "</td>"
                            // Kolom ASSESMENT
                            + "<td valign='top'>"
                            + "G" + nullToStrip(rs2.getString("gravida"))
                            + " P" + nullToStrip(rs2.getString("partus"))
                            + " A" + nullToStrip(rs2.getString("aborsi")) + "<br/>"
                            + "Pro SC a/i : " + "<br/>"
                            + nullToStrip(rs2.getString("pro_sc"))
                            + "</td>"
                            // Kolom PLANNING
                            + "<td valign='top'>"
                            + "<ul style='margin-top:2px; padding-left:5px; list-style-type: disc;'>"
                            + (planningList.length() == 0 ? "-" : planningList.toString())
                            + "</ul>"
                            + "<br/>Petugas : " + nullToStrip(rs2.getString("nip"))
                            + " - " + nullToStrip(rs2.getString("nama_petugas"))
                            + "</td>"
                            + "</tr>"
                    );
                }

                htmlContent.append(
                        "</table>"
                        + "</td>"
                        + "</tr>"
                );
            }
        } catch (Exception e) {
            System.out.println("Notifikasi Observasi Pro Operasi : " + e);
        } finally {
            if (rs2 != null) {
                try {
                    rs2.close();
                } catch (Exception e) {
                }
            }
        }
    }

