    private void menampilkanTransferPasien(String norawat) {
        try {
            if (ChkInformConcern.isSelected()) {
                PreparedStatement psMain = null;   // CHANGED: statement lokal agar bisa ditutup
                ResultSet rs2 = null;              // CHANGED: lokal, shadow field rs2
                try {
                    // Query Join Data SIMRS Java + Data TTD Web Canvas + Petugas & Dokter
                    String sql = "SELECT t.*, "
                            + "  COALESCE(ttd.nama_petugas_menyerahkan, p1.nama) AS nama_menyerahkan_fix, "
                            + "  COALESCE(ttd.nama_petugas_menerima, p2.nama) AS nama_menerima_fix, "
                            + "  ttd.signature_petugas_menyerahkan AS sig_menyerahkan, "
                            + "  ttd.signature_petugas_menerima AS sig_menerima, "
                            // CHANGED: vital sign sesudah transfer: prioritas data TTD (Web Canvas), fallback ke tabel induk
                            + "  COALESCE(NULLIF(ttd.td_sesudah_transfer,''), t.td_sesudah_transfer) AS td_sesudah_fix, "
                            + "  COALESCE(NULLIF(ttd.nadi_sesudah_transfer,''), t.nadi_sesudah_transfer) AS nadi_sesudah_fix, "
                            + "  COALESCE(NULLIF(ttd.rr_sesudah_transfer,''), t.rr_sesudah_transfer) AS rr_sesudah_fix, "
                            + "  COALESCE(NULLIF(ttd.suhu_sesudah_transfer,''), t.suhu_sesudah_transfer) AS suhu_sesudah_fix, "
                            + "  d.nm_dokter AS nama_dokter_instruksi "
                            + "FROM transfer_pasien_antar_ruang t "
                            // CHANGED: join TTD per transfer (kolom di tabel TTD bernama tgl_transfer)
                            + "LEFT JOIN transfer_pasien_antar_ruang_ttd ttd "
                            + "       ON t.no_rawat = ttd.no_rawat AND t.tanggal_transfer = ttd.tgl_transfer "
                            + "LEFT JOIN petugas p1 ON t.nip_menyerahkan = p1.nip "
                            + "LEFT JOIN petugas p2 ON t.nip_menerima = p2.nip "
                            + "LEFT JOIN dokter d ON t.kd_dokter_instruksi = d.kd_dokter "
                            + "WHERE t.no_rawat = ? " // CHANGED: prepared statement (anti SQL injection)
                            + "ORDER BY t.tanggal_transfer";        // CHANGED: urutan stabil

                    psMain = koneksi.prepareStatement(sql);
                    psMain.setString(1, norawat);
                    rs2 = psMain.executeQuery();

                    int seqTransfer = 0; // CHANGED: penomoran transfer

                    while (rs2.next()) { // CHANGED: if -> while
                        seqTransfer++;

                        // Ambil string Base64 TTD (hanya proses jika valid data:image)
                        String rawSigMenyerahkan = rs2.getString("sig_menyerahkan");
                        String rawSigMenerima = rs2.getString("sig_menerima");

                        // CHANGED: key file unik per transfer agar tidak saling menimpa
                        String urlPetugasMenyerahkan = (rawSigMenyerahkan != null && rawSigMenyerahkan.contains("data:image"))
                                ? simpanDanAmbilUrlTtd(rawSigMenyerahkan, "trf_menyerahkan", norawat + "_" + seqTransfer) : "";
                        String urlPetugasMenerima = (rawSigMenerima != null && rawSigMenerima.contains("data:image"))
                                ? simpanDanAmbilUrlTtd(rawSigMenerima, "trf_menerima", norawat + "_" + seqTransfer) : "";

                        String namaMenyerahkan = nullSafe(rs2.getString("nama_menyerahkan_fix"));
                        String namaMenerima = nullSafe(rs2.getString("nama_menerima_fix"));

                        // ---- Section Header ----
                        htmlContent.append(
                                "<tr class='isi'>"
                                + "<td valign='top' width='2%'></td>"
                                + "<td valign='top' width='18%'></td>"
                                + "<td valign='top' width='1%' align='center'>:</td>"
                                + "<td valign='top' width='79%'>"
                                + "<table width='100%' border='0' align='center' cellpadding='10' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td valign='middle' bgcolor='#0284c7' align='center' width='100%' "
                                + "style='font-weight:bold; color:white;'>LEMBAR TRANSFER PASIEN ANTAR RUANG (HANDOVER) #" + seqTransfer + "</td>" // CHANGED: bernomor
                                + "</tr>"
                                + "</table>"
                        );

                        // ---- 1. Detail Waktu & Unit Handover ----
                        htmlContent.append(
                                "<table width='100%' border='0' align='center' cellpadding='4' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td width='25%' style='font-size:11px;'><b>Tgl Masuk</b></td>"
                                + "<td width='25%' style='font-size:11px;'>: " + nullSafe(rs2.getString("tanggal_masuk")) + "</td>"
                                + "<td width='25%' style='font-size:11px;'><b>Tgl &amp; Jam Transfer</b></td>"
                                + "<td width='25%' style='font-size:11px;'>: " + nullSafe(rs2.getString("tanggal_transfer")) + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td style='font-size:11px;'><b>Petugas / Unit Pengirim</b></td>"
                                + "<td style='font-size:11px;'>: " + nullSafe(rs2.getString("nama_menghubungi")) + " (" + nullSafe(rs2.getString("unit_menghubungi")) + ")</td>"
                                + "<td style='font-size:11px;'><b>Petugas / Unit Penerima</b></td>"
                                + "<td style='font-size:11px;'>: " + nullSafe(rs2.getString("nama_dihubungi")) + " (" + nullSafe(rs2.getString("unit_dihubungi")) + ")</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td style='font-size:11px;'><b>Alasan Transfer</b></td>"
                                + "<td style='font-size:11px;'>: " + nullSafe(rs2.getString("alasan_transfer")) + "</td>"
                                + "<td style='font-size:11px;'><b>Kategori / Pendamping</b></td>"
                                + "<td style='font-size:11px;'>: " + nullSafe(rs2.getString("kategori_pasien")) + " / " + nullSafe(rs2.getString("nama_pendamping")) + "</td>"
                                + "</tr>"
                                + "</table>"
                        );

                        // ---- 2. Informasi Klinis Pasien ----
                        htmlContent.append(
                                "<table width='100%' border='1' align='center' cellpadding='4' cellspacing='0' "
                                + "class='tbl_form' style='border-collapse:collapse; font-size:10px; margin-top:4px;'>"
                                + "<tr>"
                                + "<td bgcolor='#e2e8f0' width='30%'><b>Diagnosa Medis</b></td>"
                                + "<td style='font-size:10px;'>" + nullSafe(rs2.getString("diagnosa")).replaceAll("\n", "<br>") + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td bgcolor='#e2e8f0'><b>Indikasi Rawat Inap</b></td>"
                                + "<td style='font-size:10px;'>" + nullSafe(rs2.getString("indikasi_rawat")).replaceAll("\n", "<br>") + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td bgcolor='#e2e8f0'><b>Riwayat Penyakit</b></td>"
                                + "<td style='font-size:10px;'>" + nullSafe(rs2.getString("riwayat_penyakit")).replaceAll("\n", "<br>") + "</td>"
                                + "</tr>"
                                + "</table>"
                        );

                        // ---- 3. Vital Signs Sebelum & Sesudah Transfer ----
                        String spo2Sebelum = nullSafeCol(rs2, "spo2_sebelum_transfer");
                        String spo2SbDisplay = spo2Sebelum.isEmpty() ? "-" : (spo2Sebelum.contains("%") ? spo2Sebelum : spo2Sebelum + " %");
                        String spo2Sesudah = nullSafeCol(rs2, "spo2_sesudah_transfer");
                        String spo2StDisplay = spo2Sesudah.isEmpty() ? "-" : (spo2Sesudah.contains("%") ? spo2Sesudah : spo2Sesudah + " %");

                        htmlContent.append(
                                "<table width='100%' border='1' align='center' cellpadding='4' cellspacing='0' "
                                + "class='tbl_form' style='border-collapse:collapse; font-size:10px; margin-top:4px;'>"
                                + "<tr>"
                                + "<td bgcolor='#bae6fd' colspan='4' align='center'><b>PEMERIKSAAN KONDISI PASIEN</b></td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td bgcolor='#f1f5f9' width='25%'><b>A. Sebelum Transfer</b></td>"
                                + "<td width='25%'>Kesadaran: <b>" + nullSafeCol(rs2, "kesadaran_sebelum_transfer") + "</b> | KU: <b>" + nullSafeCol(rs2, "keadaan_umum_sebelum_transfer") + "</b></td>"
                                + "<td width='25%'>TD: " + nullSafe(rs2.getString("td_sebelum_transfer")) + " mmHg | Nadi: " + nullSafe(rs2.getString("nadi_sebelum_transfer")) + " x/m</td>"
                                + "<td width='25%'>RR: " + nullSafe(rs2.getString("rr_sebelum_transfer")) + " x/m | Suhu: " + nullSafe(rs2.getString("suhu_sebelum_transfer")) + " °C | SpO2: " + spo2SbDisplay + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td bgcolor='#f1f5f9'><b>B. Sesudah Transfer</b></td>"
                                // CHANGED: pakai kolom hasil COALESCE (TTD -> fallback induk)
                                + "<td>Kesadaran: <b>" + nullSafeCol(rs2, "kesadaran_sesudah_transfer") + "</b> | KU: <b>" + nullSafeCol(rs2, "keadaan_umum_sesudah_transfer") + "</b></td>"
                                + "<td>TD: " + nullSafe(rs2.getString("td_sesudah_fix")) + " mmHg | Nadi: " + nullSafe(rs2.getString("nadi_sesudah_fix")) + " x/m</td>"
                                + "<td>RR: " + nullSafe(rs2.getString("rr_sesudah_fix")) + " x/m | Suhu: " + nullSafe(rs2.getString("suhu_sesudah_fix")) + " °C | SpO2: " + spo2StDisplay + "</td>"
                                + "</tr>"
                                + "</table>"
                        );

                        // ---- 3b. Alat Terpasang & Riwayat Pemberian Obat ----
                        // Catatan: tabel alat & obat berkunci per kunjungan (no_rawat), jadi sama untuk tiap transfer
                        StringBuilder sbAlat = new StringBuilder();
                        PreparedStatement psAlat = null;
                        ResultSet rsAlat = null;
                        try {
                            psAlat = koneksi.prepareStatement("SELECT nama_alat, tanggal_pemasangan FROM transfer_pasien_antar_ruang_alat WHERE no_rawat = ?");
                            psAlat.setString(1, norawat);
                            rsAlat = psAlat.executeQuery();
                            int countAlat = 0;
                            while (rsAlat.next()) {
                                char letter = (char) ('a' + countAlat);
                                String tglAlat = nullSafe(rsAlat.getString("tanggal_pemasangan"));
                                sbAlat.append("<tr>")
                                        .append("<td width='60%'><b>").append(letter).append(".</b> ").append(nullSafe(rsAlat.getString("nama_alat"))).append("</td>")
                                        .append("<td width='40%'>Tgl: ").append(tglAlat.isEmpty() ? "-" : tglAlat).append("</td>")
                                        .append("</tr>");
                                countAlat++;
                            }
                            if (countAlat == 0) {
                                sbAlat.append("<tr><td colspan='2' style='color:#64748b; font-style:italic;'>Tidak ada alat terpasang</td></tr>");
                            }
                        } catch (Exception eAlat) {
                            System.out.println("Error fetch transfer_pasien_antar_ruang_alat: " + eAlat);
                        } finally {
                            if (rsAlat != null) try {
                                rsAlat.close();
                            } catch (Exception ignored) {
                            }
                            if (psAlat != null) try {
                                psAlat.close();
                            } catch (Exception ignored) {
                            }
                        }

                        StringBuilder sbObat = new StringBuilder();
                        PreparedStatement psObat = null;
                        ResultSet rsObat = null;
                        try {
                            psObat = koneksi.prepareStatement("SELECT nama_obat, dosis, jam_pemberian, sisa_obat FROM transfer_pasien_antar_ruang_riwayat_obat WHERE no_rawat = ?");
                            psObat.setString(1, norawat);
                            rsObat = psObat.executeQuery();
                            int countObat = 0;
                            while (rsObat.next()) {
                                char letter = (char) ('a' + countObat);
                                String jam = nullSafe(rsObat.getString("jam_pemberian"));
                                String sisa = nullSafe(rsObat.getString("sisa_obat"));
                                sbObat.append("<tr>")
                                        .append("<td><b>").append(letter).append(".</b> ").append(nullSafe(rsObat.getString("nama_obat"))).append("</td>")
                                        .append("<td>").append(nullSafe(rsObat.getString("dosis"))).append("</td>")
                                        .append("<td>").append(jam.isEmpty() ? "-" : jam + " WIB").append("</td>")
                                        .append("<td>").append(sisa.isEmpty() ? "-" : "Jumlah " + sisa).append("</td>")
                                        .append("</tr>");
                                countObat++;
                            }
                            if (countObat == 0) {
                                sbObat.append("<tr><td colspan='4' style='color:#64748b; font-style:italic;'>Tidak ada riwayat pemberian obat</td></tr>");
                            }
                        } catch (Exception eObat) {
                            System.out.println("Error fetch transfer_pasien_antar_ruang_riwayat_obat: " + eObat);
                        } finally {
                            if (rsObat != null) try {
                                rsObat.close();
                            } catch (Exception ignored) {
                            }
                            if (psObat != null) try {
                                psObat.close();
                            } catch (Exception ignored) {
                            }
                        }

                        htmlContent.append(
                                "<table width='100%' border='1' align='center' cellpadding='4' cellspacing='0' "
                                + "class='tbl_form' style='border-collapse:collapse; font-size:10px; margin-top:4px;'>"
                                + "<tr>"
                                + "<td bgcolor='#e2e8f0' colspan='2' align='center'><b>RINGKASAN KONDISI PASIEN — ALAT TERPASANG &amp; OBAT YANG SUDAH DIBERIKAN</b></td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td width='45%' valign='top'>"
                                + "<table width='100%' border='1' cellpadding='3' cellspacing='0' style='border-collapse:collapse; font-size:10px;'>"
                                + "<tr bgcolor='#f1f5f9'>"
                                + "<td colspan='2'><b>Alat-alat yang terpasang &amp; Tanggal pemasangan</b></td>"
                                + "</tr>"
                                + sbAlat.toString()
                                + "</table>"
                                + "</td>"
                                + "<td width='55%' valign='top'>"
                                + "<table width='100%' border='1' cellpadding='3' cellspacing='0' style='border-collapse:collapse; font-size:10px;'>"
                                + "<tr bgcolor='#f1f5f9'>"
                                + "<td><b>Obat yang sudah diberikan</b></td>"
                                + "<td><b>Dosis</b></td>"
                                + "<td><b>Jam Pemberian</b></td>"
                                + "<td><b>Sisa Obat</b></td>"
                                + "</tr>"
                                + sbObat.toString()
                                + "</table>"
                                + "</td>"
                                + "</tr>"
                                + "</table>"
                        );

                        // ---- 4. Dokumen & Dokter ----
                        htmlContent.append(
                                "<table width='100%' border='0' align='center' cellpadding='4' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td width='25%' style='font-size:10px;'><b>Dokumen Penyerta</b></td>"
                                + "<td style='font-size:10px;'>: " + nullSafe(rs2.getString("dokumen_penyerta")) + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td style='font-size:10px;'><b>Dokter Menginstruksikan</b></td>"
                                + "<td style='font-size:10px;'>: " + nullSafe(rs2.getString("nama_dokter_instruksi")) + "</td>"
                                + "</tr>"
                                + "<tr>"
                                + "<td style='font-size:10px;'><b>Catatan Tambahan</b></td>"
                                + "<td style='font-size:10px;'>: " + nullSafe(rs2.getString("catatan_tambahan")) + "</td>"
                                + "</tr>"
                                + "</table>"
                        );

                        // ---- 5. Signature Blocks (2 Actors Web Handover Canvas) ----
                        htmlContent.append(
                                "<table width='100%' border='0' align='center' cellpadding='6' cellspacing='0' class='tbl_form'>"
                                + "<tr>"
                                + "<td align='center' width='50%' style='font-size:10px; border-top:1px dashed #ccc;'>"
                                + "<b>Petugas Yang Menyerahkan (Pengirim)</b><br>"
                                + sigImgHtml(urlPetugasMenyerahkan, "60", "30") + "<br>"
                                + "<u>" + (namaMenyerahkan.isEmpty() ? "..........................." : namaMenyerahkan) + "</u>"
                                + "</td>"
                                + "<td align='center' width='50%' style='font-size:10px; border-top:1px dashed #ccc;'>"
                                + "<b>Petugas Yang Menerima (Penerima)</b><br>"
                                + sigImgHtml(urlPetugasMenerima, "60", "30") + "<br>"
                                + "<u>" + (namaMenerima.isEmpty() ? "..........................." : namaMenerima) + "</u>"
                                + "</td>"
                                + "</tr>"
                                + "</table>"
                                + "</td>"
                                + "</tr>"
                        );

                    } // end while rs2.next()

                } catch (Exception e) {
                    System.out.println("Notifikasi TransferPasien : " + e);
                } finally {
                    // CHANGED: tutup result set dan statement
                    if (rs2 != null) {
                        rs2.close();
                    }
                    if (psMain != null) {
                        psMain.close();
                    }
                }
            }
        } catch (Exception e) {
            System.out.println("Notif TransferPasien outer : " + e);
        }
    }

// ============================================================
// SHARED HELPERS — add these once to your class
// ============================================================
    /**
     * Returns empty string instead of null for safe DB values
     */
    private String nullSafe(String value) {
        return value != null ? value : "";
    }

    private String nullSafeCol(ResultSet rs, String colName) {
        try {
            return nullSafe(rs.getString(colName));
        } catch (Exception e) {
            return "";
        }
    }

    /**
     * Produces an <img> HTML tag from a file URL, or a dashes placeholder if
     * url is null.
     *
     * @param url URL returned by simpanDanAmbilUrlTtd() — may be null if no
     * signature
     * @param width HTML width attribute (e.g. "80")
     * @param height HTML height attribute (e.g. "40")
     */
    private String sigImgHtml(String url, String width, String height) {
        if (url == null || url.trim().isEmpty()) {
            return "<span style='font-size:9px; color:#94a3b8;'>..................</span>";
        }
        return "<img src='" + url + "' width='" + width + "' height='" + height
                + "' style='object-fit:contain; display:block; margin:2px auto;'/>";
    }

    // ============================================================
// Helper method to format list of items
    private String formatLabelList(String rawJson, Map<String, String> labelMap) {
        if (rawJson == null || rawJson.trim().isEmpty() || rawJson.equals("[]")) {
            return "-";
        }
        List<String> formattedItems = new ArrayList<>();
        for (Map.Entry<String, String> entry : labelMap.entrySet()) {
            if (rawJson.contains(entry.getKey())) {
                formattedItems.add(entry.getValue());
            }
        }
        return formattedItems.isEmpty() ? "-" : String.join(", ", formattedItems);
    }

